import { EventEmitter } from 'node:events';
import { Readable } from 'node:stream';
import { fetchClientMetadataResource } from './cimd-client-metadata-fetch';

jest.mock('@better-auth/core/utils/host', () => ({
  isPublicRoutableHost: jest.fn(() => true),
}));
jest.mock('node:dns/promises', () => ({ lookup: jest.fn() }));
jest.mock('node:https', () => ({ request: jest.fn() }));

const { isPublicRoutableHost } = jest.requireMock('@better-auth/core/utils/host') as {
  isPublicRoutableHost: jest.Mock;
};
const { lookup } = jest.requireMock('node:dns/promises') as { lookup: jest.Mock };
const { request } = jest.requireMock('node:https') as { request: jest.Mock };

function fakeRequest(
  cb: (response: Readable & { statusCode: number; headers: Record<string, string> }) => void,
  statusCode = 200,
  body = '{"ok":true}',
) {
  const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
  req.end = jest.fn();
  req.destroy = jest.fn((err: Error) => req.emit('error', err));
  process.nextTick(() => {
    const stream = Readable.from([Buffer.from(body)]) as Readable & {
      statusCode: number;
      headers: Record<string, string>;
      statusMessage?: string;
    };
    stream.statusCode = statusCode;
    stream.headers = { 'content-type': 'application/json' };
    cb(stream);
  });
  return req;
}

describe('fetchClientMetadataResource', () => {
  beforeEach(() => {
    isPublicRoutableHost.mockReturnValue(true);
    lookup.mockReset();
    request.mockReset();
  });

  it('fetches and returns a metadata document', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    let captured: { lookup: (...a: unknown[]) => void } | undefined;
    request.mockImplementation((_url, opts, cb) => {
      captured = opts as { lookup: (...a: unknown[]) => void };
      return fakeRequest(cb);
    });
    const response = await fetchClientMetadataResource('https://example.com/meta');
    expect(response.status).toBe(200);
    expect(await response.text()).toBe('{"ok":true}');

    // The pinned lookup must return the validated address for both the
    // all-addresses and single-address forms Node may ask for.
    const all = jest.fn();
    captured!.lookup('example.com', { all: true }, all);
    expect(all).toHaveBeenCalledWith(null, [{ address: '93.184.216.34', family: 4 }]);
    const single = jest.fn();
    captured!.lookup('example.com', {}, single);
    expect(single).toHaveBeenCalledWith(null, '93.184.216.34', 4);
  });

  it('discards the body for a 204', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation((_url, _opts, cb) => fakeRequest(cb, 204, ''));
    const response = await fetchClientMetadataResource('https://example.com/meta');
    expect(response.status).toBe(204);
    expect(await response.text()).toBe('');
  });

  it('rejects a non-https URL and a non-GET method before any network call', async () => {
    await expect(fetchClientMetadataResource('http://example.com/meta')).rejects.toThrow(/HTTPS/);
    await expect(
      fetchClientMetadataResource('https://example.com/meta', { method: 'POST' }),
    ).rejects.toThrow(/GET and HEAD/);
    expect(request).not.toHaveBeenCalled();
  });

  it('rejects when DNS returns no addresses or a private one', async () => {
    lookup.mockResolvedValueOnce([]);
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /no DNS addresses/,
    );

    lookup.mockResolvedValueOnce([{ address: '10.0.0.1', family: 4 }]);
    isPublicRoutableHost.mockReturnValueOnce(false);
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /public-routable/,
    );
  });

  it('rejects on request error', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation(() => {
      const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
      req.end = jest.fn();
      req.destroy = jest.fn();
      process.nextTick(() => req.emit('error', new Error('network down')));
      return req;
    });
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /network down/,
    );
  });

  it('rejects on a stalled socket timeout', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation(() => {
      const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
      req.end = jest.fn();
      req.destroy = jest.fn((err: Error) => req.emit('error', err));
      process.nextTick(() => req.emit('timeout'));
      return req;
    });
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /timed out/,
    );
  });

  it('flattens array response headers and accepts an IPv6-only resolution', async () => {
    lookup.mockResolvedValue([{ address: '2606:2800:220:1:248:1893:25c8:1946', family: 6 }]);
    request.mockImplementation((_url, _opts, cb) => {
      const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
      req.end = jest.fn();
      req.destroy = jest.fn();
      process.nextTick(() => {
        const stream = Readable.from([Buffer.from('{}')]) as Readable & {
          statusCode: number;
          headers: Record<string, string | string[]>;
        };
        stream.statusCode = 200;
        stream.headers = { 'x-multi': ['a', 'b'], 'x-one': 'c' };
        cb(stream as never);
      });
      return req;
    });
    const response = await fetchClientMetadataResource('https://example.com/meta');
    expect(response.headers.get('x-multi')).toBe('a, b');
    expect(response.headers.get('x-one')).toBe('c');
  });

  it('rejects an out-of-range HTTP status instead of throwing', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation((_url, _opts, cb) => fakeRequest(cb, 700, ''));
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /invalid HTTP status/,
    );
  });

  it('rejects a malformed status line instead of throwing', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation((_url, _opts, cb) => {
      const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
      req.end = jest.fn();
      req.destroy = jest.fn();
      process.nextTick(() => {
        const stream = Readable.from([Buffer.from('{}')]) as Readable & {
          statusCode: number;
          statusMessage: string;
          headers: Record<string, string>;
        };
        stream.statusCode = 200;
        stream.statusMessage = 'bad\nvalue';
        stream.headers = {};
        cb(stream as never);
      });
      return req;
    });
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /Invalid statusText/,
    );
  });

  it('answers a HEAD probe with no body', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    request.mockImplementation((_url, _opts, cb) => fakeRequest(cb, 200, '{"a":1}'));
    const response = await fetchClientMetadataResource('https://example.com/meta', {
      method: 'HEAD',
    });
    expect(response.status).toBe(200);
    expect(await response.text()).toBe('');
  });

  it('allows a private host in self-hosted mode regardless of the public gate', async () => {
    const previous = process.env['MANIFEST_MODE'];
    process.env['MANIFEST_MODE'] = 'selfhosted';
    try {
      isPublicRoutableHost.mockReturnValue(false);
      lookup.mockResolvedValue([{ address: '10.0.0.5', family: 4 }]);
      request.mockImplementation((_url, _opts, cb) => fakeRequest(cb));
      expect((await fetchClientMetadataResource('https://lan.local/meta')).status).toBe(200);

      // A host.containers.internal-style link-local address is allowed too.
      lookup.mockResolvedValue([{ address: '169.254.1.2', family: 4 }]);
      expect((await fetchClientMetadataResource('https://lan.local/meta')).status).toBe(200);
    } finally {
      if (previous === undefined) delete process.env['MANIFEST_MODE'];
      else process.env['MANIFEST_MODE'] = previous;
    }
  });

  it('blocks cloud-metadata addresses even in self-hosted mode', async () => {
    const previous = process.env['MANIFEST_MODE'];
    process.env['MANIFEST_MODE'] = 'selfhosted';
    try {
      lookup.mockResolvedValue([{ address: '169.254.169.254', family: 4 }]);
      await expect(fetchClientMetadataResource('https://lan.local/meta')).rejects.toThrow(
        /cloud metadata/,
      );

      // Alibaba/OCI IMDS, covered by the shared classifier.
      lookup.mockResolvedValue([{ address: '100.100.100.200', family: 4 }]);
      await expect(fetchClientMetadataResource('https://lan.local/meta')).rejects.toThrow(
        /cloud metadata/,
      );
    } finally {
      if (previous === undefined) delete process.env['MANIFEST_MODE'];
      else process.env['MANIFEST_MODE'] = previous;
    }
  });

  it('blocks a private host in cloud mode', async () => {
    const previous = process.env['MANIFEST_MODE'];
    process.env['MANIFEST_MODE'] = 'cloud';
    try {
      lookup.mockResolvedValue([{ address: '10.0.0.5', family: 4 }]);
      isPublicRoutableHost.mockReturnValueOnce(false);
      await expect(fetchClientMetadataResource('https://lan.local/meta')).rejects.toThrow(
        /public-routable/,
      );
    } finally {
      if (previous === undefined) delete process.env['MANIFEST_MODE'];
      else process.env['MANIFEST_MODE'] = previous;
    }
  });

  it('rejects a direct IP literal', async () => {
    await expect(fetchClientMetadataResource('https://127.0.0.1/meta')).rejects.toThrow(
      /IP literal/,
    );
    expect(lookup).not.toHaveBeenCalled();
  });

  it('lets a self-hosted lookup failure fall through to the request resolver', async () => {
    const previous = process.env['MANIFEST_MODE'];
    process.env['MANIFEST_MODE'] = 'selfhosted';
    try {
      lookup.mockRejectedValue(new Error('ENOTFOUND'));
      request.mockImplementation((_url, opts, cb) => {
        expect((opts as { lookup?: unknown }).lookup).toBeUndefined();
        return fakeRequest(cb);
      });
      expect((await fetchClientMetadataResource('https://lan.local/meta')).status).toBe(200);
    } finally {
      if (previous === undefined) delete process.env['MANIFEST_MODE'];
      else process.env['MANIFEST_MODE'] = previous;
    }
  });

  it('rejects a protocol upgrade and destroys its socket', async () => {
    lookup.mockResolvedValue([{ address: '93.184.216.34', family: 4 }]);
    const socket = { destroy: jest.fn() };
    request.mockImplementation(() => {
      const req = new EventEmitter() as EventEmitter & { end: jest.Mock; destroy: jest.Mock };
      req.end = jest.fn();
      req.destroy = jest.fn();
      process.nextTick(() => req.emit('upgrade', {}, socket));
      return req;
    });
    await expect(fetchClientMetadataResource('https://example.com/meta')).rejects.toThrow(
      /upgrade/,
    );
    expect(socket.destroy).toHaveBeenCalled();
  });
});

import { PricingSyncService } from './pricing-sync.service';

// Edge-case coverage for PricingSyncService that does not fit cleanly into the
// main spec file (which is already long). Split out per the test-file size cap
// in CLAUDE.md. The primary spec is `pricing-sync.service.spec.ts`.

let fetchSpy: jest.SpyInstance;

describe('PricingSyncService edge cases', () => {
  let service: PricingSyncService;

  beforeEach(() => {
    service = new PricingSyncService();
    fetchSpy = jest.spyOn(global, 'fetch');
  });

  afterEach(() => {
    fetchSpy.mockRestore();
  });

  describe('refreshCache fetch timeout', () => {
    // The fetch helper sets up `setTimeout(() => controller.abort(), 10_000)`.
    // If anything during the fetch+parse pipeline times out, the abort signal
    // fires and the in-flight fetch/json promise rejects with an AbortError.
    // The catch handler logs and returns null → refreshCache resolves with 0.
    //
    // Without this test, a regression that drops the abort signal (e.g. a
    // refactor that re-fetches without forwarding `controller.signal`) would
    // silently allow the request to hang for the undici default header
    // timeout — exactly the class of bug that motivated the non-blocking
    // startup fix (#1894).
    it('passes the AbortController signal to fetch so it can be aborted on stall', async () => {
      let capturedSignal: AbortSignal | undefined;
      fetchSpy.mockImplementation(async (_url, options) => {
        const init = options as { signal: AbortSignal };
        capturedSignal = init.signal;
        return {
          ok: true,
          json: async () => ({ data: [] }),
        } as unknown as Response;
      });

      await service.refreshCache();

      // The signal must be an AbortSignal so the surrounding setTimeout(abort)
      // can actually terminate a stalled upstream connection. If a refactor
      // dropped the signal, the test fails immediately.
      expect(capturedSignal).toBeInstanceOf(AbortSignal);
      // It should not already be aborted right after a clean request — the
      // timer is cleared in the finally block.
      expect(capturedSignal!.aborted).toBe(false);
    });

    // Simulates a real upstream stall: the signal fires (because the abort
    // timer expired upstream) and res.json() rejects with AbortError. We pin
    // the exact contract that the catch handler:
    //  - returns null from fetchOpenRouterModels
    //  - causes refreshCache to return 0
    //  - logs an error
    //  - does not mutate cache or lastFetchedAt
    it('returns 0 and logs when res.json() rejects with AbortError mid-parse', async () => {
      const abortErr = new Error('The operation was aborted');
      abortErr.name = 'AbortError';
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => {
          throw abortErr;
        },
      } as unknown as Response);

      const loggerSpy = jest.spyOn(service['logger'], 'error').mockImplementation();
      try {
        const count = await service.refreshCache();

        expect(count).toBe(0);
        expect(loggerSpy).toHaveBeenCalledWith(
          expect.stringMatching(/Failed to fetch OpenRouter models.*AbortError/),
        );
        // No cache mutation on abort.
        expect(service.getAll().size).toBe(0);
        expect(service.getLastFetchedAt()).toBeNull();
      } finally {
        loggerSpy.mockRestore();
      }
    });

    // Belt-and-suspenders: if fetch itself rejects with AbortError (network
    // stall *before* headers, not after), refreshCache must still resolve 0
    // and log the error. This guards the other branch of the catch.
    it('returns 0 and logs when fetch itself rejects with AbortError', async () => {
      const abortErr = new Error('The operation was aborted');
      abortErr.name = 'AbortError';
      fetchSpy.mockRejectedValue(abortErr);

      const loggerSpy = jest.spyOn(service['logger'], 'error').mockImplementation();
      try {
        const count = await service.refreshCache();
        expect(count).toBe(0);
        expect(loggerSpy).toHaveBeenCalledWith(
          expect.stringMatching(/Failed to fetch OpenRouter models.*AbortError/),
        );
      } finally {
        loggerSpy.mockRestore();
      }
    });

    // Verify clearTimeout is called on the abort timer regardless of which
    // branch wins (success or thrown). If clearTimeout was moved out of
    // finally and the throw branch leaked the timer, the test below would
    // see a missing call.
    it('clears the abort timer on successful fetch (no leaked handles)', async () => {
      const clearTimeoutSpy = jest.spyOn(global, 'clearTimeout');
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => ({ data: [] }),
      } as unknown as Response);

      try {
        await service.refreshCache();
        expect(clearTimeoutSpy).toHaveBeenCalled();
      } finally {
        clearTimeoutSpy.mockRestore();
      }
    });

    it('clears the abort timer when fetch throws (no leaked handles)', async () => {
      const clearTimeoutSpy = jest.spyOn(global, 'clearTimeout');
      fetchSpy.mockRejectedValue(new Error('network down'));

      const loggerSpy = jest.spyOn(service['logger'], 'error').mockImplementation();
      try {
        const count = await service.refreshCache();
        expect(count).toBe(0);
        expect(clearTimeoutSpy).toHaveBeenCalled();
      } finally {
        loggerSpy.mockRestore();
        clearTimeoutSpy.mockRestore();
      }
    });
  });

  describe('refreshCache concurrency', () => {
    // The service is invoked by both the @Cron decorator (daily) and by
    // manual triggers so concurrent calls are possible. Two parallel calls
    // each compute their own newCache, and the last assignment to
    // `this.cache` wins. This test pins the contract: the final cache is
    // one of the two complete result sets — never a half-merged
    // intermediate. If a future change introduces shared mutable state
    // inside refreshCache, this test will start failing.
    it('handles two parallel refreshCache calls without corrupting the cache', async () => {
      const respA = {
        ok: true,
        json: async () => ({
          data: [{ id: 'openai/gpt-A', pricing: { prompt: '0.001', completion: '0.002' } }],
        }),
      } as unknown as Response;
      const respB = {
        ok: true,
        json: async () => ({
          data: [{ id: 'openai/gpt-B', pricing: { prompt: '0.003', completion: '0.004' } }],
        }),
      } as unknown as Response;

      fetchSpy.mockResolvedValueOnce(respA).mockResolvedValueOnce(respB);

      const [countA, countB] = await Promise.all([service.refreshCache(), service.refreshCache()]);

      expect(countA).toBe(1);
      expect(countB).toBe(1);
      expect(fetchSpy).toHaveBeenCalledTimes(2);

      // Whichever assignment landed last owns the cache. The other entry
      // must not be present, and the cache size must equal the size of one
      // complete fetch (never the union — that would prove the cache was
      // mutated mid-flight).
      const all = service.getAll();
      expect(all.size).toBe(1);
      const hasA = all.has('openai/gpt-A');
      const hasB = all.has('openai/gpt-B');
      expect(hasA !== hasB).toBe(true);
    });

    // When both calls return the same dataset, the result must be identical
    // to a single call. Catches a race where one writer could clear the
    // cache after the other populated it.
    it('is idempotent when called twice in parallel with identical responses', async () => {
      fetchSpy.mockImplementation(
        async () =>
          ({
            ok: true,
            json: async () => ({
              data: [
                { id: 'openai/gpt-4o', pricing: { prompt: '0.001', completion: '0.002' } },
                { id: 'anthropic/claude-x', pricing: { prompt: '0.003', completion: '0.006' } },
              ],
            }),
          }) as unknown as Response,
      );

      const [countA, countB] = await Promise.all([service.refreshCache(), service.refreshCache()]);

      expect(countA).toBe(2);
      expect(countB).toBe(2);

      const all = service.getAll();
      expect(all.size).toBe(2);
      expect(all.has('openai/gpt-4o')).toBe(true);
      expect(all.has('anthropic/claude-x')).toBe(true);
      expect(all.get('openai/gpt-4o')!.input).toBe(0.001);
      expect(all.get('anthropic/claude-x')!.output).toBe(0.006);
    });

    // If one of two concurrent refreshes fails (e.g. transient 503), the
    // other must still populate the cache. The failure must not clobber a
    // successful sibling's writes because the failure branch returns early
    // before assigning this.cache.
    it('does not clobber the cache when a concurrent refresh fails', async () => {
      fetchSpy.mockResolvedValueOnce({
        ok: true,
        json: async () => ({
          data: [{ id: 'openai/gpt-good', pricing: { prompt: '0.001', completion: '0.002' } }],
        }),
      } as unknown as Response);
      fetchSpy.mockResolvedValueOnce({ ok: false, status: 503 } as unknown as Response);

      const loggerSpy = jest.spyOn(service['logger'], 'error').mockImplementation();
      try {
        const [countA, countB] = await Promise.all([
          service.refreshCache(),
          service.refreshCache(),
        ]);

        // One call saw the good response (count=1), the other saw 503 (count=0).
        expect(new Set([countA, countB])).toEqual(new Set([0, 1]));

        // The good model must be present regardless of completion order —
        // the 503 branch returns early before reassigning this.cache.
        expect(service.getAll().has('openai/gpt-good')).toBe(true);
        expect(service.getAll().size).toBe(1);
      } finally {
        loggerSpy.mockRestore();
      }
    });
  });
});

import { PricingSyncService } from './pricing-sync.service';

let fetchSpy: jest.SpyInstance;

describe('PricingSyncService', () => {
  let service: PricingSyncService;

  beforeEach(() => {
    service = new PricingSyncService();
    fetchSpy = jest.spyOn(global, 'fetch');
  });

  afterEach(() => {
    fetchSpy.mockRestore();
  });

  describe('onModuleInit', () => {
    it('kicks off refreshCache without blocking and populates the cache', async () => {
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => ({
          data: [
            {
              id: 'openai/gpt-4o',
              pricing: { prompt: '0.0000025', completion: '0.00001' },
            },
          ],
        }),
      });

      // onModuleInit is fire-and-forget (must not block boot — see #1894);
      // whenInitialized() resolves once the startup fetch has landed.
      service.onModuleInit();
      await service.whenInitialized();
      expect(fetchSpy).toHaveBeenCalledWith(
        'https://openrouter.ai/api/v1/models',
        expect.objectContaining({ signal: expect.any(AbortSignal) }),
      );
      expect(service.getAll().size).toBeGreaterThan(0);
    });

    it('does not reject when refreshCache rejects', async () => {
      // Make refreshCache itself reject (not just fetch) to trigger the .catch() handler
      jest.spyOn(service, 'refreshCache').mockRejectedValue(new Error('Unexpected failure'));

      service.onModuleInit();
      // The startup failure is swallowed by the .catch; whenInitialized resolves
      await expect(service.whenInitialized()).resolves.toBeUndefined();
    });
  });

  describe('whenInitialized', () => {
    it('resolves immediately when onModuleInit has not run', async () => {
      await expect(service.whenInitialized()).resolves.toBeUndefined();
    });
  });

  describe('refreshCache', () => {
    it('populates cache with successful response', async () => {
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => ({
          data: [
            {
              id: 'anthropic/claude-opus-4',
              name: 'Anthropic: Claude Opus 4',
              context_length: 200000,
              pricing: { prompt: '0.000015', completion: '0.000075' },
            },
            {
              id: 'openai/gpt-4o',
              name: 'OpenAI: GPT-4o',
              pricing: { prompt: '0.0000025', completion: '0.00001' },
            },
          ],
        }),
      });

      const count = await service.refreshCache();
      expect(count).toBe(2);

      const all = service.getAll();
      // Models stored under full OpenRouter ID only
      expect(all.has('anthropic/claude-opus-4')).toBe(true);
      expect(all.has('openai/gpt-4o')).toBe(true);
      // No canonical-only entries
      expect(all.has('claude-opus-4')).toBe(false);
      expect(all.has('gpt-4o')).toBe(false);

      const claude = all.get('anthropic/claude-opus-4')!;
      expect(claude.input).toBe(0.000015);
      expect(claude.output).toBe(0.000075);
      expect(claude.contextWindow).toBe(200000);
      expect(claude.displayName).toBe('Claude Opus 4');

      const gpt = all.get('openai/gpt-4o')!;
      expect(gpt.input).toBe(0.0000025);
      expect(gpt.output).toBe(0.00001);
      expect(gpt.contextWindow).toBeUndefined();
      expect(gpt.displayName).toBe('GPT-4o');
    });

    it('stores under full ID for openrouter/ prefixed models', async () => {
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => ({
          data: [
            {
              id: 'openrouter/auto',
              name: 'Auto (best for prompt)',
              pricing: { prompt: '0.000003', completion: '0.000015' },
            },
          ],
        }),
      });

      const count = await service.refreshCache();
      expect(count).toBe(1);
      // openrouter/ models keep full ID as canonical
      expect(service.getAll().has('openrouter/auto')).toBe(true);
    });

    it('returns 0 when API returns non-OK status', async () => {
      fetchSpy.mockResolvedValue({ ok: false, status: 503 });

      const count = await service.refreshCache();
      expect(count).toBe(0);
      expect(service.getAll().size).toBe(0);
    });

    it('returns 0 when fetch throws', async () => {
      fetchSpy.mockRejectedValue(new Error('Network error'));

      const count = await service.refreshCache();
      expect(count).toBe(0);
      expect(service.getAll().size).toBe(0);
    });

    it('handles response with undefined data field', async () => {
      fetchSpy.mockResolvedValue({
        ok: true,
        json: async () => ({}),
      });

      const count = await service.refreshCache();
      expect(count).toBe(0);
    });

