        }),
      ).toBe(true);
    });
  });
});

import { Logger } from '@nestjs/common';
import { decrypt, encrypt } from '../common/utils/crypto.util';
import {
  BATCH_SIZE,
  ENCRYPTED_COLUMNS,
  SecretReencryptionService,
} from './secret-reencryption.service';

const CURRENT = 'current-secret-'.padEnd(40, 'c');
const PREVIOUS = 'previous-secret-'.padEnd(40, 'p');
const UNKNOWN = 'unknown-secret-'.padEnd(40, 'u');

interface Row {
  id: string;
  value: string;
}

/**
 * Minimal DataSource stand-in. `pages` maps a table name to the pages its
 * keyset SELECT returns in order; every other SQL shape is recorded.
 */
function buildDataSource(opts: {
  acquired?: boolean;
  pages?: Record<string, Row[][]>;
  failSelectFor?: string;
  connectError?: Error;
  unlockError?: Error;
  releaseError?: Error;
  updateAffected?: number;
}) {
  const updates: Array<{ table: string; params: unknown[] }> = [];
  const pageCursor: Record<string, number> = {};
  const connect = jest.fn(async () => {
    if (opts.connectError) throw opts.connectError;
  });
  const release = jest.fn(async () => {
    if (opts.releaseError) throw opts.releaseError;
  });
  const query = jest.fn(async (sql: string, params: unknown[] = []) => {
    if (sql.includes('pg_try_advisory_lock')) return [{ acquired: opts.acquired ?? true }];
    if (sql.includes('pg_advisory_unlock')) {
      if (opts.unlockError) throw opts.unlockError;
      return [];
    }
    const table = /FROM "([^"]+)"|UPDATE "([^"]+)"/.exec(sql);
    const name = table?.[1] ?? table?.[2] ?? '';
    if (sql.startsWith('SELECT')) {
      if (opts.failSelectFor === name) throw new Error(`relation "${name}" does not exist`);
      const pages = opts.pages?.[name] ?? [];
      const index = pageCursor[name] ?? 0;
      pageCursor[name] = index + 1;
      return pages[index] ?? [];
    }
    updates.push({ table: name, params });
    return { affected: opts.updateAffected ?? 1 };
  });
  const queryRunner = { connect, query, release };
  const createQueryRunner = jest.fn(() => queryRunner);
  return {
    dataSource: { createQueryRunner } as never,
    createQueryRunner,
    connect,
    query,
    release,
    updates,
  };
}

describe('SecretReencryptionService', () => {
  const originalEnv = process.env;
  let log: jest.SpyInstance;
  let warn: jest.SpyInstance;
  let error: jest.SpyInstance;

  beforeEach(() => {
    process.env = { ...originalEnv };
    delete process.env['MANIFEST_ENCRYPTION_KEY'];
    delete process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'];
    delete process.env['BETTER_AUTH_SECRET'];
    log = jest.spyOn(Logger.prototype, 'log').mockImplementation(() => undefined);
    warn = jest.spyOn(Logger.prototype, 'warn').mockImplementation(() => undefined);
    error = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
  });

  afterEach(() => {
    process.env = originalEnv;
    jest.restoreAllMocks();
  });

  it('covers every column that encrypt() writes to', () => {
    expect(ENCRYPTED_COLUMNS.map((c) => `${c.table}.${c.column}`)).toEqual([
      'tenant_providers.api_key_encrypted',
      'agent_api_keys.key',
      'email_provider_configs.api_key_encrypted',
    ]);
  });

  it('skips with a warning when PREVIOUS is set but no current secret is configured', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({});
    await new SecretReencryptionService(ds.dataSource).onApplicationBootstrap();
    expect(warn).toHaveBeenCalledWith(expect.stringContaining('Skipping secret re-encryption'));
    expect(ds.createQueryRunner).not.toHaveBeenCalled();
  });

  it('is a no-op on a normal boot, even though the session secret is a decrypt candidate', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['BETTER_AUTH_SECRET'] = PREVIOUS;
    const ds = buildDataSource({});
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.createQueryRunner).not.toHaveBeenCalled();
    expect(log).not.toHaveBeenCalled();
  });

  it('ignores a PREVIOUS shorter than 32 chars', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = 'short';
    const ds = buildDataSource({});
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.createQueryRunner).not.toHaveBeenCalled();
  });

  it('kicks the pass off from bootstrap without awaiting it', () => {
    const ds = buildDataSource({});
    const service = new SecretReencryptionService(ds.dataSource);
    const run = jest.spyOn(service, 'run').mockResolvedValue(undefined);
    service.onApplicationBootstrap();
    expect(run).toHaveBeenCalledTimes(1);
  });

  it('logs instead of leaking an unhandled rejection when the detached pass throws', async () => {
    const ds = buildDataSource({});
    const service = new SecretReencryptionService(ds.dataSource);
    jest.spyOn(service, 'run').mockRejectedValue(new Error('pool closed'));
    service.onApplicationBootstrap();
    await new Promise((resolve) => setImmediate(resolve));
    expect(error).toHaveBeenCalledWith(expect.stringContaining('pool closed'));
  });

  it('moves on without scanning when another replica holds the lock', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({ acquired: false });
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.query).toHaveBeenCalledTimes(1);
    expect(ds.query.mock.calls[0][0]).toContain('pg_try_advisory_lock');
    expect(ds.release).toHaveBeenCalled();
  });

  it('rewrites rows under an older secret and leaves the rest alone', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const underPrevious = encrypt('sk-old', PREVIOUS);
    const underCurrent = encrypt('sk-new', CURRENT);
    const underUnknown = encrypt('sk-lost', UNKNOWN);
    const ds = buildDataSource({
      pages: {
        tenant_providers: [
          [
            { id: 'a', value: underPrevious },
            { id: 'b', value: underCurrent },
            { id: 'c', value: 'plaintext-legacy' },
            { id: 'd', value: underUnknown },
          ],
        ],
        agent_api_keys: [[{ id: 'k1', value: encrypt('mnfst_x', PREVIOUS) }]],
      },
    });

    await new SecretReencryptionService(ds.dataSource).run();

    expect(ds.updates).toHaveLength(2);
    const [first, second] = ds.updates;
    expect(first.table).toBe('tenant_providers');
    expect(first.params[1]).toBe('a');
    expect(first.params[2]).toBe(underPrevious);
    expect(decrypt(first.params[0] as string, CURRENT)).toBe('sk-old');
    expect(second.table).toBe('agent_api_keys');
    expect(decrypt(second.params[0] as string, CURRENT)).toBe('mnfst_x');

    expect(warn).toHaveBeenCalledWith(expect.stringContaining('row d'));
    expect(log).toHaveBeenCalledWith(
      expect.stringContaining(
        'tenant_providers.api_key_encrypted 4 scanned / 1 rewritten / 1 undecryptable',
      ),
    );
    expect(log).not.toHaveBeenCalledWith(expect.stringContaining('can be removed'));
    expect(ds.query).toHaveBeenCalledWith(expect.stringContaining('pg_advisory_unlock'));
    expect(ds.release).toHaveBeenCalled();
  });

  it('moves rows off the session secret when PREVIOUS names it', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['BETTER_AUTH_SECRET'] = PREVIOUS;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({
      pages: { email_provider_configs: [[{ id: 'e', value: encrypt('re_123', PREVIOUS) }]] },
    });
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.updates).toHaveLength(1);
    expect(decrypt(ds.updates[0].params[0] as string, CURRENT)).toBe('re_123');
    expect(log).toHaveBeenCalledWith(expect.stringContaining('1 rewritten'));
  });

  it('does not count a rewrite another process won', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({
      updateAffected: 0,
      pages: { agent_api_keys: [[{ id: 'k', value: encrypt('mnfst_z', PREVIOUS) }]] },
    });
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.updates).toHaveLength(1);
    expect(log).toHaveBeenCalledWith(expect.stringContaining('1 scanned / 0 rewritten'));
  });

  it('withholds the removal hint while any row is undecryptable', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({
      pages: { tenant_providers: [[{ id: 'u', value: encrypt('sk-lost', UNKNOWN) }]] },
    });
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.updates).toHaveLength(0);
    expect(log).not.toHaveBeenCalledWith(expect.stringContaining('can be removed'));
  });

  it('pages through full batches with the last id as the cursor', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const full = Array.from({ length: BATCH_SIZE }, (_, i) => ({
      id: `id-${String(i).padStart(4, '0')}`,
      value: 'plain',
    }));
    const ds = buildDataSource({ pages: { tenant_providers: [full, []] } });
    await new SecretReencryptionService(ds.dataSource).run();
    const selects = ds.query.mock.calls.filter(([sql]) => String(sql).startsWith('SELECT'));
    const providerSelects = selects.filter(([sql]) => String(sql).includes('"tenant_providers"'));
    expect(providerSelects).toHaveLength(2);
    expect(providerSelects[1][1]).toEqual([`id-${String(BATCH_SIZE - 1).padStart(4, '0')}`]);
    expect(ds.updates).toHaveLength(0);
    expect(log).toHaveBeenCalledWith(expect.stringContaining('can be removed'));
  });

  it('keeps going when one table fails and reports it in the summary', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({
      failSelectFor: 'tenant_providers',
      pages: { agent_api_keys: [[{ id: 'k', value: encrypt('mnfst_y', PREVIOUS) }]] },
    });
    await new SecretReencryptionService(ds.dataSource).run();
    expect(ds.updates).toHaveLength(1);
    expect(log).toHaveBeenCalledWith(
      expect.stringContaining('tenant_providers.api_key_encrypted failed (relation'),
    );
    expect(error).not.toHaveBeenCalled();
  });

  it('logs and swallows a failure to connect, then still releases the runner', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({
      connectError: new Error('db down'),
      releaseError: new Error('x'),
    });
    await expect(new SecretReencryptionService(ds.dataSource).run()).resolves.toBeUndefined();
    expect(error).toHaveBeenCalledWith(expect.stringContaining('db down'));
    expect(ds.query).not.toHaveBeenCalledWith(expect.stringContaining('pg_advisory_unlock'));
    expect(ds.release).toHaveBeenCalled();
  });

  it('ignores an unlock failure', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({ unlockError: new Error('unlock'), pages: {} });
    await expect(new SecretReencryptionService(ds.dataSource).run()).resolves.toBeUndefined();
    expect(error).not.toHaveBeenCalled();
  });

  it('reports non-Error throwables by their string form', async () => {
    process.env['MANIFEST_ENCRYPTION_KEY'] = CURRENT;
    process.env['MANIFEST_ENCRYPTION_KEY_PREVIOUS'] = PREVIOUS;
    const ds = buildDataSource({});
    ds.connect.mockRejectedValueOnce('plain string');
    await new SecretReencryptionService(ds.dataSource).run();
    expect(error).toHaveBeenCalledWith(expect.stringContaining('plain string'));
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";

// Spy that `createAuthClient` from `better-auth/solid` resolves to. The
// module under test (`auth-client.ts`) imports this symbol and invokes it
// once at module-load time, so we mock it before any dynamic import below.
// Use `vi.hoisted` so the spy is available to the hoisted `vi.mock` factory.
const { createAuthClientMock, stripeClientMock } = vi.hoisted(() => ({
  createAuthClientMock: vi.fn((config: unknown) => ({
    __mockClient: true,
    config,
  })),
  // `stripeClient` is a factory the module passes into `plugins`. We tag the
  // return value so the test can assert the plugin was actually wired in.
  stripeClientMock: vi.fn((opts: unknown) => ({ __stripePlugin: true, opts })),
}));

vi.mock("better-auth/solid", () => ({
  createAuthClient: createAuthClientMock,
}));

vi.mock("@better-auth/stripe/client", () => ({
  stripeClient: stripeClientMock,
}));

describe("authClient", () => {
  beforeEach(() => {
    // Each test re-imports the module to re-trigger the top-level
    // `createAuthClient({...})` call against a fresh mock state.
    vi.resetModules();
    createAuthClientMock.mockClear();
    stripeClientMock.mockClear();

    // Pin `window.location.origin` to a deterministic value. jsdom would
    // otherwise return "http://localhost:3000", which is fine but we want
    // tests to be insensitive to harness defaults.
    vi.stubGlobal("window", {
      ...window,
      location: {
        ...window.location,
        origin: "https://app.manifest.build",
      },
    } as Window & typeof globalThis);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("creates client with correct baseURL from window.location.origin", async () => {
    await import("../../src/services/auth-client.js");

    expect(createAuthClientMock).toHaveBeenCalledTimes(1);
    const config = createAuthClientMock.mock.calls[0][0] as {
      baseURL: string;
      basePath: string;
    };
    expect(config.baseURL).toBe("https://app.manifest.build");
  });

  it("creates client with basePath /api/auth", async () => {
    await import("../../src/services/auth-client.js");

    expect(createAuthClientMock).toHaveBeenCalledTimes(1);
    const config = createAuthClientMock.mock.calls[0][0] as {
      baseURL: string;
      basePath: string;
    };
    expect(config.basePath).toBe("/api/auth");
  });

  it("registers the stripe subscription client plugin", async () => {
    await import("../../src/services/auth-client.js");

    // `stripeClient` must be called once with subscription mode enabled...
    expect(stripeClientMock).toHaveBeenCalledTimes(1);
    expect(stripeClientMock.mock.calls[0][0]).toEqual({ subscription: true });

    // ...and the returned plugin must be passed into `createAuthClient`'s
    // `plugins` array, which is what widens the client type with the
    // `subscription` namespace in production.
    const config = createAuthClientMock.mock.calls[0][0] as {
      plugins: unknown[];
    };
    expect(config.plugins).toHaveLength(1);
    expect(config.plugins[0]).toBe(stripeClientMock.mock.results[0].value);
  });

  it("exports authClient as createAuthClient return type", async () => {
    const mod = await import("../../src/services/auth-client.js");

    // The exported `authClient` must be the exact value returned by
    // `createAuthClient`. We return a tagged object from the mock so we
    // can assert identity, not just shape.
    expect(mod.authClient).toBeDefined();
    expect((mod.authClient as unknown as { __mockClient: boolean }).__mockClient).toBe(true);
    expect(mod.authClient).toBe(createAuthClientMock.mock.results[0].value);
  });

  it("initialization does not throw errors", async () => {
    // The module evaluates its top-level `createAuthClient({...})` call
    // synchronously on import. A throw inside `createAuthClient` would
    // surface here as a rejected promise from the dynamic import.
    await expect(import("../../src/services/auth-client.js")).resolves.toBeDefined();
  });

  it("re-reads window.location.origin on each module load", async () => {
    // First load uses the stubbed origin from beforeEach.
    await import("../../src/services/auth-client.js");
    expect(createAuthClientMock.mock.calls[0][0]).toMatchObject({
      baseURL: "https://app.manifest.build",
    });

    // Swap the origin and reload. We expect a fresh `createAuthClient`
    // call with the new origin, proving the module is not cached against
    // a stale value baked at first import.
    vi.resetModules();
    createAuthClientMock.mockClear();
    stripeClientMock.mockClear();
    vi.stubGlobal("window", {
      ...window,
      location: {
        ...window.location,
        origin: "http://localhost:3001",
      },
    } as Window & typeof globalThis);

    await import("../../src/services/auth-client.js");
    expect(createAuthClientMock).toHaveBeenCalledTimes(1);
    expect(createAuthClientMock.mock.calls[0][0]).toMatchObject({
      baseURL: "http://localhost:3001",
      basePath: "/api/auth",
    });
  });
});

import { Logger } from '@nestjs/common';
import { DataSource, Repository } from 'typeorm';

import { BackfillState } from '../../entities/backfill-state.entity';
import {
  MESSAGE_PROVIDER_BACKFILL_LOCK_KEY,
  MESSAGE_PROVIDER_BACKFILL_NAME,
  MessageProviderBackfillBootService,
} from './message-provider-backfill.boot.service';

function makeLock(locked: boolean) {
  return {
    connect: jest.fn(async () => undefined),
    release: jest.fn(async () => undefined),
    query: jest.fn(async (sql: string) =>
      sql.includes('pg_try_advisory_lock') ? [{ locked }] : undefined,
    ),
  };
}

function makeState(completed: boolean) {
  const execute = jest.fn(async () => undefined);
  const orIgnore = jest.fn(() => ({ execute }));
  const values = jest.fn(() => ({ orIgnore }));
  const into = jest.fn(() => ({ values }));
  const insert = jest.fn(() => ({ into }));
  const createQueryBuilder = jest.fn(() => ({ insert }));
  const countBy = jest.fn(async () => (completed ? 1 : 0));
  const repo = { countBy, createQueryBuilder } as unknown as Repository<BackfillState>;
  return { repo, countBy, createQueryBuilder, insert, into, values, orIgnore, execute };
}

const UNLOCK = 'SELECT pg_advisory_unlock($1)';
const TRYLOCK = 'SELECT pg_try_advisory_lock($1) AS locked';

describe('MessageProviderBackfillBootService', () => {
  let logSpy: jest.SpyInstance;
  let errSpy: jest.SpyInstance;
  const originalEnv = process.env['NODE_ENV'];
  const originalMode = process.env['MANIFEST_MODE'];

  beforeEach(() => {
    process.env['MANIFEST_MODE'] = 'selfhosted';
    logSpy = jest.spyOn(Logger.prototype, 'log').mockImplementation(() => undefined);
    errSpy = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
  });
  afterEach(() => {
    logSpy.mockRestore();
    errSpy.mockRestore();
    process.env['NODE_ENV'] = originalEnv;
    if (originalMode === undefined) delete process.env['MANIFEST_MODE'];
    else process.env['MANIFEST_MODE'] = originalMode;
  });

  describe('onApplicationBootstrap', () => {
    it('does nothing outside production', () => {
      process.env['NODE_ENV'] = 'test';
      const ds = { createQueryRunner: jest.fn() } as unknown as DataSource;
      new MessageProviderBackfillBootService(ds, makeState(false).repo).onApplicationBootstrap();
      expect(ds.createQueryRunner).not.toHaveBeenCalled();
    });

    it('leaves Cloud coordination to the direct request-backfill connection', () => {
      process.env['NODE_ENV'] = 'production';
      process.env['MANIFEST_MODE'] = 'cloud';
      const ds = { createQueryRunner: jest.fn() } as unknown as DataSource;

      new MessageProviderBackfillBootService(ds, makeState(false).repo).onApplicationBootstrap();

      expect(ds.createQueryRunner).not.toHaveBeenCalled();
    });

    it('fires the backfill in production and logs (not throws) on failure', async () => {
      process.env['NODE_ENV'] = 'production';
      const state = makeState(false);
      state.countBy.mockRejectedValue(new Error('db down'));
      const ds = { createQueryRunner: jest.fn() } as unknown as DataSource;

      new MessageProviderBackfillBootService(ds, state.repo).onApplicationBootstrap();
      await new Promise((resolve) => setImmediate(resolve));

      expect(errSpy).toHaveBeenCalledWith(expect.stringContaining('post-deploy backfill failed'));
    });

    it('waits and retries after advisory-lock contention', async () => {
      jest.useFakeTimers();
      process.env['NODE_ENV'] = 'production';
      const state = makeState(false);
      state.countBy.mockResolvedValueOnce(0).mockResolvedValueOnce(1);
      const lock = makeLock(false);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;

      new MessageProviderBackfillBootService(ds, state.repo).onApplicationBootstrap();
      await jest.advanceTimersByTimeAsync(30_000);

      expect(state.countBy).toHaveBeenCalledTimes(2);
      expect(lock.release).toHaveBeenCalled();
      jest.useRealTimers();
    });

    it('keeps retrying until the competing backfill completes', async () => {
      jest.useFakeTimers();
      process.env['NODE_ENV'] = 'production';
      const state = makeState(false);
      const lock = makeLock(false);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;

      new MessageProviderBackfillBootService(ds, state.repo).onApplicationBootstrap();
      await jest.advanceTimersByTimeAsync(30_000 * 12);

      expect(state.countBy.mock.calls.length).toBeGreaterThan(10);
      expect(errSpy).not.toHaveBeenCalled();
      state.countBy.mockResolvedValue(1);
      await jest.advanceTimersByTimeAsync(30_000);
      jest.useRealTimers();
    });
  });

  describe('runOnce', () => {
    it('returns immediately when already marked complete', async () => {
      const state = makeState(true);
      const ds = { createQueryRunner: jest.fn() } as unknown as DataSource;
      const runner = jest.fn();
      await expect(
        new MessageProviderBackfillBootService(ds, state.repo).runOnce(runner),
      ).resolves.toBe(true);
      expect(ds.createQueryRunner).not.toHaveBeenCalled();
      expect(runner).not.toHaveBeenCalled();
    });

    it('skips (without unlocking) when another instance holds the advisory lock', async () => {
      const lock = makeLock(false);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;
      const runner = jest.fn();
      await expect(
        new MessageProviderBackfillBootService(ds, makeState(false).repo).runOnce(runner),
      ).resolves.toBe(false);
      expect(lock.query).toHaveBeenCalledWith(TRYLOCK, [MESSAGE_PROVIDER_BACKFILL_LOCK_KEY]);
      expect(runner).not.toHaveBeenCalled();
      expect(lock.query).not.toHaveBeenCalledWith(UNLOCK, [MESSAGE_PROVIDER_BACKFILL_LOCK_KEY]);
      expect(lock.release).toHaveBeenCalled();
    });

    it('runs the backfill under the lock, marks complete, then unlocks and releases', async () => {
      const lock = makeLock(true);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;
      const state = makeState(false);
      const runner = jest.fn(async () => ({ windows: 3, stamped: 42 }));

      await expect(
        new MessageProviderBackfillBootService(ds, state.repo).runOnce(runner),
      ).resolves.toBe(true);

      expect(runner).toHaveBeenCalledWith(
        ds,
        expect.objectContaining({ logger: expect.anything() }),
      );
      expect(state.values).toHaveBeenCalledWith({ name: MESSAGE_PROVIDER_BACKFILL_NAME });
      expect(state.execute).toHaveBeenCalled();
      expect(lock.query).toHaveBeenCalledWith(UNLOCK, [MESSAGE_PROVIDER_BACKFILL_LOCK_KEY]);
      expect(lock.release).toHaveBeenCalled();
    });

    it('re-checks under the lock and skips the run if a peer finished first', async () => {
      const lock = makeLock(true);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;
      const state = makeState(false);
      state.countBy.mockResolvedValueOnce(0).mockResolvedValueOnce(1); // free, then taken
      const runner = jest.fn();

      await expect(
        new MessageProviderBackfillBootService(ds, state.repo).runOnce(runner),
      ).resolves.toBe(true);

      expect(runner).not.toHaveBeenCalled();
      expect(lock.query).toHaveBeenCalledWith(UNLOCK, [MESSAGE_PROVIDER_BACKFILL_LOCK_KEY]);
      expect(lock.release).toHaveBeenCalled();
    });

    it('unlocks and releases even if the backfill throws', async () => {
      const lock = makeLock(true);
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;
      const runner = jest.fn(async () => {
        throw new Error('boom');
      });

      await expect(
        new MessageProviderBackfillBootService(ds, makeState(false).repo).runOnce(runner),
      ).rejects.toThrow('boom');
      expect(lock.query).toHaveBeenCalledWith(UNLOCK, [MESSAGE_PROVIDER_BACKFILL_LOCK_KEY]);
      expect(lock.release).toHaveBeenCalled();
    });

    it('swallows an unlock failure in the finally block (still releases, no throw)', async () => {
      const lock = {
        connect: jest.fn(async () => undefined),
        release: jest.fn(async () => undefined),
        query: jest.fn(async (sql: string) => {
          if (sql.includes('pg_try_advisory_lock')) {
            return [{ locked: true }];
          }
          throw new Error('unlock failed');
        }),
      };
      const ds = { createQueryRunner: jest.fn(() => lock) } as unknown as DataSource;
      const runner = jest.fn(async () => ({ windows: 1, stamped: 1 }));

      await expect(
        new MessageProviderBackfillBootService(ds, makeState(false).repo).runOnce(runner),
      ).resolves.toBe(true);
      expect(lock.release).toHaveBeenCalled();
    });

    it('defaults to the real backfill runner when none is injected', async () => {
      const lock = makeLock(true);
      const ds = {
        createQueryRunner: jest.fn(() => lock),
        // gateway.nextWindowEnd → no rows → backfill completes with zero windows
        query: jest.fn(async (sql: string) =>
          sql.includes('FROM "agent_messages"') ? [{ end_id: null }] : undefined,
        ),
      } as unknown as DataSource;
      const state = makeState(false);

      await new MessageProviderBackfillBootService(ds, state.repo).runOnce();

      expect(state.execute).toHaveBeenCalled(); // ran to completion → marked done
      expect(lock.release).toHaveBeenCalled();
    });
  });
});

