import { QueryRunner } from 'typeorm';

import { AddUserProviderIdToAgentMessages1792000000000 } from './1792000000000-AddUserProviderIdToAgentMessages';

describe('AddUserProviderIdToAgentMessages1792000000000', () => {
  const migration = new AddUserProviderIdToAgentMessages1792000000000();
  let queries: string[];
  let queryRunner: QueryRunner;

  beforeEach(() => {
    queries = [];
    queryRunner = {
      query: jest.fn(async (sql: string) => {
        queries.push(sql);
      }),
    } as unknown as QueryRunner;
  });

  describe('up', () => {
    it('adds the nullable column first, with IF NOT EXISTS', async () => {
      await migration.up(queryRunner);

      expect(queries[0]).toContain(
        'ALTER TABLE "agent_messages" ADD COLUMN IF NOT EXISTS "user_provider_id" varchar',
      );
    });

    it('adds the FK with ON DELETE SET NULL (validated — trivial against an all-NULL column)', async () => {
      await migration.up(queryRunner);

      const fk = queries.find((q) =>
        q.includes('ADD CONSTRAINT "FK_agent_messages_user_provider"'),
      );
      expect(fk).toBeDefined();
      expect(fk).toContain('FOREIGN KEY ("user_provider_id") REFERENCES "user_providers"("id")');
      expect(fk).toContain('ON DELETE SET NULL ON UPDATE NO ACTION');
      // Validated, not NOT VALID — the column is empty so there is nothing to scan.
      expect(fk).not.toContain('NOT VALID');
    });

    it('builds the covering index in the migration (TenantProviders later renames it)', async () => {
      await migration.up(queryRunner);

      const idx = queries.find((q) =>
        q.includes('CREATE INDEX "IDX_agent_messages_user_provider"'),
      );
      expect(idx).toBeDefined();
      expect(idx).toContain('"user_provider_id", "tenant_id", "timestamp" DESC');
    });

    it('does no inline historical backfill — that runs post-deploy', async () => {
      await migration.up(queryRunner);

      expect(queries.some((q) => q.includes('UPDATE "agent_messages"'))).toBe(false);
      // add column, add FK, create index — nothing else.
      expect(queries).toHaveLength(3);
    });
  });

  describe('down', () => {
    it('drops the index, then the FK, then the column', async () => {
      await migration.down(queryRunner);

      expect(queries[0]).toContain('DROP INDEX IF EXISTS "IDX_agent_messages_user_provider"');
      expect(queries[1]).toContain('DROP CONSTRAINT IF EXISTS "FK_agent_messages_user_provider"');
      expect(queries[2]).toContain('DROP COLUMN IF EXISTS "user_provider_id"');
    });
  });
});

import { fetchJson, fetchMutate, routingPath } from './core.js';
import type { AuthType, ModelRoute, ResponseMode, OutputModality } from './routing.js';

export interface SpecificityAssignment {
  id: string;
  agent_id: string;
  category: string;
  is_active: boolean;
  override_route: ModelRoute | null;
  auto_assigned_route: ModelRoute | null;
  fallback_routes: ModelRoute[] | null;
  output_modality?: OutputModality;
  response_mode?: ResponseMode;
  updated_at: string;
}

export function getSpecificityAssignments(agentName: string) {
  return fetchJson<SpecificityAssignment[]>(routingPath(agentName, 'specificity'));
}

export function toggleSpecificity(agentName: string, category: string, active: boolean) {
  return fetchMutate<SpecificityAssignment>(
    routingPath(agentName, `specificity/${encodeURIComponent(category)}/toggle`),
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ active }),
    },
  );
}

export function overrideSpecificity(
  agentName: string,
  category: string,
  model: string,
  provider: string,
  authType?: AuthType,
  providerKeyLabel?: string,
) {
  const body: Record<string, unknown> = { model, provider };
  if (authType) {
    body.authType = authType;
    const route: ModelRoute = providerKeyLabel
      ? { provider, authType, model, keyLabel: providerKeyLabel }
      : { provider, authType, model };
    body.route = route;
  }
  if (providerKeyLabel) body.providerKeyLabel = providerKeyLabel;
  return fetchMutate<SpecificityAssignment>(
    routingPath(agentName, `specificity/${encodeURIComponent(category)}`),
    {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    },
  );
}

export function resetSpecificity(agentName: string, category: string) {
  return fetchMutate(routingPath(agentName, `specificity/${encodeURIComponent(category)}`), {
    method: 'DELETE',
  });
}

export function setSpecificityResponseMode(
  agentName: string,
  category: string,
  responseMode: ResponseMode,
) {
  return fetchMutate<SpecificityAssignment>(
    routingPath(agentName, `specificity/${encodeURIComponent(category)}/response-mode`),
    {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ response_mode: responseMode }),
    },
  );
}

export function setSpecificityFallbacks(
  agentName: string,
  category: string,
  models: string[],
  routes?: ModelRoute[],
) {
  const body: Record<string, unknown> = { models };
  if (routes && routes.length === models.length) body.routes = routes;
  return fetchMutate<string[]>(
    routingPath(agentName, `specificity/${encodeURIComponent(category)}/fallbacks`),
    {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    },
  );
}

export function clearSpecificityFallbacks(agentName: string, category: string) {
  return fetchMutate(
    routingPath(agentName, `specificity/${encodeURIComponent(category)}/fallbacks`),
    { method: 'DELETE' },
  );
}

export function resetAllSpecificity(agentName: string) {
  return fetchMutate(routingPath(agentName, 'specificity/reset-all'), {
    method: 'POST',
  });
}

