      mockDataSource.query.mockResolvedValueOnce([]); // checkBetterAuthUser: no user
      auth.api.signUpEmail.mockRejectedValueOnce(new Error('signup failed'));
      const errorSpy = jest
        .spyOn((service as unknown as { logger: { error: jest.Mock } }).logger, 'error')
        .mockImplementation(() => undefined);

      await expect(service.onModuleInit()).resolves.toBeUndefined();
      expect(errorSpy).toHaveBeenCalledWith(expect.stringContaining('signup failed'));

      errorSpy.mockRestore();
    });

    it('keeps the Better Auth migration fatal — its failure still aborts boot', async () => {
      // The migration that creates Better Auth's own tables runs BEFORE the
      // guarded demo-data block and must remain fatal: without those tables the
      // app cannot authenticate at all, so a failure here should propagate.
      const ctx = await auth.$context;
      (ctx.runMigrations as jest.Mock).mockRejectedValueOnce(new Error('migration boom'));

      await expect(service.onModuleInit()).rejects.toThrow('migration boom');
    });

    it('should skip api key insert when getAdminUserId returns null', async () => {
      // checkBetterAuthUser: user exists (skip signUpEmail)
      mockDataSource.query.mockResolvedValueOnce([{ id: 'x' }]);
      // Every subsequent getAdminUserId call (seedTenantAndAgent, seedApiKey,
      // seedAgentMessages) returns no rows → null.
      mockDataSource.query.mockResolvedValue([]);

      mockApiKeyRepo.count.mockResolvedValue(0);

      await service.onModuleInit();

      expect(mockApiKeyRepo.insert).not.toHaveBeenCalled();
    });

    it('should handle getAdminUserId query failure with Error and return null', async () => {
      // checkBetterAuthUser: user exists (skip signUpEmail)
      mockDataSource.query.mockResolvedValueOnce([{ id: 'x' }]);
      // Every subsequent getAdminUserId query throws an Error → caught → null.
      mockDataSource.query.mockRejectedValue(new Error('connection lost'));
      mockApiKeyRepo.count.mockResolvedValue(0);

      await service.onModuleInit();

      // seedApiKey should skip insert because getAdminUserId returned null
      expect(mockApiKeyRepo.insert).not.toHaveBeenCalled();
    });

    it('should handle getAdminUserId query failure with non-Error and return null', async () => {
      // checkBetterAuthUser: user exists (skip signUpEmail)
      mockDataSource.query.mockResolvedValueOnce([{ id: 'x' }]);
      // Every subsequent getAdminUserId query throws a non-Error → caught → null.
      mockDataSource.query.mockRejectedValue('string rejection');
      mockApiKeyRepo.count.mockResolvedValue(0);

      await service.onModuleInit();

      // seedApiKey should skip insert because getAdminUserId returned null
      expect(mockApiKeyRepo.insert).not.toHaveBeenCalled();
    });
  });

  describe('seedDemoCohorts', () => {
    it('seeds the clean + legacy cohorts when the legacy agent does not yet exist', async () => {
      mockAgentRepo.count.mockResolvedValue(0);

      await service.onModuleInit();

      // The new legacy (olduser) agent is flipped to complexity-on so the
      // deprecated surfaces stay visible.
      expect(mockAgentRepo.update).toHaveBeenCalledWith(
        { id: 'seed-agent-old-001' },
        { complexity_routing_enabled: true },
      );
      // A brand-new legacy "old" user is signed up.
      expect(auth.api.signUpEmail).toHaveBeenCalledWith(
        expect.objectContaining({
          body: expect.objectContaining({ email: 'olduser@manifest.build' }),
        }),
      );
      // The legacy cohort tenant is created.
      expect(mockTenantRepo.insert).toHaveBeenCalledWith(
        expect.objectContaining({ id: 'seed-tenant-old-001' }),
      );
    });

    it('skips cohort seeding when the legacy agent already exists', async () => {
      // mockAgentRepo.count defaults to 1 (set in beforeEach) → cohort is a no-op,
      // while the normal admin/demo-agent seed still runs.
      await service.onModuleInit();

      expect(mockAgentRepo.update).not.toHaveBeenCalled();
      expect(mockTenantRepo.insert).toHaveBeenCalledWith(
        expect.objectContaining({ id: 'seed-tenant-001' }),
      );
    });
  });
});

import { Test } from '@nestjs/testing';
import { getDataSourceToken } from '@nestjs/typeorm';
import { ConfigService } from '@nestjs/config';
import { DataSource } from 'typeorm';
import { DbTuningService } from './db-tuning.service';

describe('DbTuningService', () => {
  let service: DbTuningService;
  let query: jest.Mock;
  let configValue: boolean | undefined;

  async function build(): Promise<void> {
    query = jest.fn().mockResolvedValue(undefined);
    const moduleRef = await Test.createTestingModule({
      providers: [
        DbTuningService,
        { provide: getDataSourceToken(), useValue: { query } as unknown as DataSource },
        { provide: ConfigService, useValue: { get: () => configValue } },
      ],
    }).compile();
    service = moduleRef.get(DbTuningService);
  }

  beforeEach(() => {
    configValue = undefined;
    jest.spyOn(console, 'warn').mockImplementation(() => undefined);
  });

  afterEach(() => jest.restoreAllMocks());

  it('applies every planner default as a role-level ALTER ROLE on bootstrap', async () => {
    configValue = true;
    await build();
    await service.onApplicationBootstrap();

    expect(query).toHaveBeenCalledTimes(DbTuningService.SETTINGS.length);
    expect(query).toHaveBeenCalledWith('ALTER ROLE CURRENT_USER SET jit = off');
    expect(query).toHaveBeenCalledWith("ALTER ROLE CURRENT_USER SET work_mem = '24MB'");
    expect(query).toHaveBeenCalledWith('ALTER ROLE CURRENT_USER SET random_page_cost = 1.1');
  });

  it('skips tuning entirely when DB_TUNE_SESSION is disabled', async () => {
    configValue = false;
    await build();
    await service.onApplicationBootstrap();
    expect(query).not.toHaveBeenCalled();
  });

  it('continues applying remaining settings when one ALTER ROLE fails', async () => {
    configValue = true;
    await build();
    query.mockRejectedValueOnce(new Error('permission denied'));

    await expect(service.apply()).resolves.toBeUndefined();
    // All three are still attempted despite the first rejecting.
    expect(query).toHaveBeenCalledTimes(DbTuningService.SETTINGS.length);
  });

  it('swallows non-Error rejections without throwing', async () => {
    configValue = true;
    await build();
    query.mockRejectedValueOnce('boom');
    await expect(service.apply()).resolves.toBeUndefined();
  });

  it('does not log success when every ALTER ROLE fails', async () => {
    configValue = true;
    await build();
    query.mockRejectedValue(new Error('permission denied'));
    const logSpy = jest.spyOn((service as unknown as { logger: { log: jest.Mock } }).logger, 'log');

    await expect(service.apply()).resolves.toBeUndefined();

    expect(query).toHaveBeenCalledTimes(DbTuningService.SETTINGS.length);
    // The unconditional success log must not fire when nothing was applied.
    expect(logSpy).not.toHaveBeenCalled();
  });
});

import { OllamaSyncService } from './ollama-sync.service';

/* ── Helpers ── */

function makeMockProviderRepo() {
  return {
    find: jest.fn().mockResolvedValue([]),
  };
}

function makeMockDiscovery() {
  return {
    discoverModels: jest.fn().mockResolvedValue([]),
  };
}

function mockFetchSuccess(models: unknown[]) {
  return jest.fn().mockResolvedValue({
    ok: true,
    json: jest.fn().mockResolvedValue({ models }),
  });
}

function mockFetchFailure(error: Error) {
  return jest.fn().mockRejectedValue(error);
}

function mockFetchNonOk(status: number) {
  return jest.fn().mockResolvedValue({
    ok: false,
    status,
    json: jest.fn(),
  });
}

/* ── Tests ── */

describe('OllamaSyncService', () => {
  let service: OllamaSyncService;
  let mockProviderRepo: ReturnType<typeof makeMockProviderRepo>;
  let mockDiscovery: ReturnType<typeof makeMockDiscovery>;
  const originalFetch = global.fetch;

  beforeEach(() => {
    mockProviderRepo = makeMockProviderRepo();
    mockDiscovery = makeMockDiscovery();
    service = new OllamaSyncService(mockProviderRepo as never, mockDiscovery as never);
  });

  afterEach(() => {
    global.fetch = originalFetch;
  });

  /* ── No active Ollama providers: direct API ping ── */

  describe('no active Ollama providers (direct API ping)', () => {
    beforeEach(() => {
      mockProviderRepo.find.mockResolvedValue([]);
    });

    it('should return count from Ollama API when reachable', async () => {
      global.fetch = mockFetchSuccess([{ name: 'llama3' }, { name: 'phi4' }]);

      const result = await service.sync();

      expect(result).toEqual({ count: 2 });
      expect(mockDiscovery.discoverModels).not.toHaveBeenCalled();
    });

    it('should return count 0 when Ollama is unreachable', async () => {
      global.fetch = mockFetchFailure(new Error('connect ECONNREFUSED 127.0.0.1:11434'));

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should return count 0 when fetch times out (abort)', async () => {
      global.fetch = mockFetchFailure(new DOMException('aborted', 'AbortError'));

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should abort fetch when setTimeout callback fires', async () => {
      jest.useFakeTimers();
      global.fetch = jest.fn().mockImplementation((_url: string, opts?: RequestInit) => {
        return new Promise<Response>((_resolve, reject) => {
          if (opts?.signal) {
            opts.signal.addEventListener('abort', () => {
              reject(new DOMException('aborted', 'AbortError'));
            });
          }
        });
      });

      const syncPromise = service.sync();

      // Flush microtask queue so providerRepo.find() resolves and fetch is called
      await Promise.resolve();
      await Promise.resolve();

      // Advance timers to trigger the 3000ms abort timeout callback
      jest.advanceTimersByTime(3000);

      const result = await syncPromise;
      expect(result).toEqual({ count: 0 });

      jest.useRealTimers();
    });

    it('should return count 0 on non-ok HTTP response', async () => {
      global.fetch = mockFetchNonOk(500);

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should return count 0 on 404 response', async () => {
      global.fetch = mockFetchNonOk(404);

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should return count 0 when models array is empty', async () => {
      global.fetch = mockFetchSuccess([]);

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should return count 0 when models key is missing', async () => {
      global.fetch = jest.fn().mockResolvedValue({
        ok: true,
        json: jest.fn().mockResolvedValue({}),
      });

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });
  });

  /* ── Active Ollama providers: delegate to discoveryService ── */

  describe('with active Ollama providers', () => {
    it('should call discoveryService.discoverModels for each provider', async () => {
      const provider1 = { id: 'p1', provider: 'ollama', is_active: true };
      const provider2 = { id: 'p2', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider1, provider2]);
      mockDiscovery.discoverModels
        .mockResolvedValueOnce([{ id: 'model-a' }, { id: 'model-b' }])
        .mockResolvedValueOnce([{ id: 'model-c' }]);

      const result = await service.sync();

      expect(result).toEqual({ count: 3 });
      expect(mockDiscovery.discoverModels).toHaveBeenCalledTimes(2);
      expect(mockDiscovery.discoverModels).toHaveBeenCalledWith(provider1);
      expect(mockDiscovery.discoverModels).toHaveBeenCalledWith(provider2);
    });

    it('should return count 0 when discoveryService returns empty arrays', async () => {
      const provider = { id: 'p1', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider]);
      mockDiscovery.discoverModels.mockResolvedValue([]);

      const result = await service.sync();

      expect(result).toEqual({ count: 0 });
    });

    it('should not call fetch when providers exist', async () => {
      const provider = { id: 'p1', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider]);
      mockDiscovery.discoverModels.mockResolvedValue([{ id: 'a' }]);
      global.fetch = jest.fn();

      await service.sync();

      expect(global.fetch).not.toHaveBeenCalled();
    });

    it('should accumulate counts across multiple providers', async () => {
      const providers = [
        { id: 'p1', provider: 'ollama', is_active: true },
        { id: 'p2', provider: 'ollama', is_active: true },
        { id: 'p3', provider: 'ollama', is_active: true },
      ];
      mockProviderRepo.find.mockResolvedValue(providers);
      mockDiscovery.discoverModels
        .mockResolvedValueOnce([{ id: 'm1' }])
        .mockResolvedValueOnce([{ id: 'm2' }, { id: 'm3' }])
        .mockResolvedValueOnce([{ id: 'm4' }, { id: 'm5' }, { id: 'm6' }]);

      const result = await service.sync();

      expect(result).toEqual({ count: 6 });
    });

    /* ── Discovery service rejection (fail-fast) ── */

    it('should rethrow when discoverModels rejects for a single provider', async () => {
      const provider = { id: 'p1', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider]);
      const discoveryError = new Error('discovery failed');
      mockDiscovery.discoverModels.mockRejectedValueOnce(discoveryError);

      await expect(service.sync()).rejects.toThrow('discovery failed');
      expect(mockDiscovery.discoverModels).toHaveBeenCalledTimes(1);
    });

    it('should halt loop on first provider rejection and not invoke later providers', async () => {
      const provider1 = { id: 'p1', provider: 'ollama', is_active: true };
      const provider2 = { id: 'p2', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider1, provider2]);
      mockDiscovery.discoverModels
        .mockRejectedValueOnce(new Error('first failed'))
        .mockResolvedValueOnce([{ id: 'm1' }]);

      await expect(service.sync()).rejects.toThrow('first failed');
      // Fail-fast: loop halts immediately; second provider is never queried
      expect(mockDiscovery.discoverModels).toHaveBeenCalledTimes(1);
      expect(mockDiscovery.discoverModels).toHaveBeenCalledWith(provider1);
      expect(mockDiscovery.discoverModels).not.toHaveBeenCalledWith(provider2);
    });

    it('should rethrow even if some providers already succeeded (no partial count)', async () => {
      const provider1 = { id: 'p1', provider: 'ollama', is_active: true };
      const provider2 = { id: 'p2', provider: 'ollama', is_active: true };
      const provider3 = { id: 'p3', provider: 'ollama', is_active: true };
      mockProviderRepo.find.mockResolvedValue([provider1, provider2, provider3]);
      mockDiscovery.discoverModels
        .mockResolvedValueOnce([{ id: 'm1' }, { id: 'm2' }])
        .mockRejectedValueOnce(new Error('second failed'))
        .mockResolvedValueOnce([{ id: 'm3' }]);

      // sync() rejects rather than returning a partial { count: 2 }
      await expect(service.sync()).rejects.toThrow('second failed');
      expect(mockDiscovery.discoverModels).toHaveBeenCalledTimes(2);
    });
  });

  /* ── Provider repo query ── */

  describe('provider lookup', () => {
    it('should query for active ollama providers', async () => {
      global.fetch = mockFetchSuccess([]);

      await service.sync();

      expect(mockProviderRepo.find).toHaveBeenCalledWith({
        where: { provider: 'ollama', is_active: true },
      });
    });

    it('should query with exact where shape (toStrictEqual)', async () => {
      global.fetch = mockFetchSuccess([]);

      await service.sync();

      expect(mockProviderRepo.find).toHaveBeenCalledTimes(1);
      const callArg = mockProviderRepo.find.mock.calls[0][0];
      // Exact structural match catches accidental field additions/removals
      // (e.g., an inverted is_active or a missing provider filter).
      expect(callArg).toStrictEqual({
        where: { provider: 'ollama', is_active: true },
      });
      expect(callArg).toEqual(
        expect.objectContaining({
          where: expect.objectContaining({
            provider: 'ollama',
            is_active: true,
          }),
        }),
      );
    });

    it('should fall through to API ping when find returns empty (simulates is_active=false filter)', async () => {
      // If is_active were inverted to false, no rows would match — the service
      // should hit the API ping branch instead of calling discoverModels.
      mockProviderRepo.find.mockResolvedValue([]);
      global.fetch = mockFetchSuccess([{ name: 'llama3' }]);

      const result = await service.sync();

      expect(result).toEqual({ count: 1 });
      expect(mockDiscovery.discoverModels).not.toHaveBeenCalled();
      expect(global.fetch).toHaveBeenCalledTimes(1);
    });
  });
});

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';

interface OpenRouterModel {
  id: string;
  name?: string;
  context_length?: number;
  architecture?: {
    input_modalities?: string[];
    output_modalities?: string[];
  };
  pricing?: {
    prompt?: string;
    completion?: string;
  };
}

interface OpenRouterResponse {
  data: OpenRouterModel[];
}

export interface OpenRouterPricingEntry {
  input: number;
  output: number;
  contextWindow?: number;
  displayName?: string;
}

const OPENROUTER_API = 'https://openrouter.ai/api/v1/models';
const FETCH_TIMEOUT_MS = 10000;

@Injectable()
export class PricingSyncService implements OnModuleInit {
  private readonly logger = new Logger(PricingSyncService.name);
  private cache = new Map<string, OpenRouterPricingEntry>();
  private lastFetchedAt: Date | null = null;
  private initialLoad: Promise<void> | null = null;

  onModuleInit(): void {
    // Kick off the startup fetch WITHOUT blocking boot. A slow or unreachable
    // OpenRouter previously stalled app.listen() — and with it Railway's
    // healthcheck — for up to undici's default header timeout (see #1894).
    // The pricing cache still warms up with real data shortly after the server
    // starts listening; ModelPricingCacheService awaits whenInitialized()
    // before its first reload so that warmup sees populated data.
    this.initialLoad = this.refreshCache()
      .then(() => undefined)
      .catch((err) => {
        this.logger.error(`Startup OpenRouter cache refresh failed: ${err}`);
      });
  }

  /** Resolves once the startup refresh has settled (success or handled error). */
  whenInitialized(): Promise<void> {
    return this.initialLoad ?? Promise.resolve();
  }

  @Cron(CronExpression.EVERY_DAY_AT_3AM)
  async refreshCache(): Promise<number> {
    this.logger.log('Refreshing OpenRouter pricing cache...');
    const data = await this.fetchOpenRouterModels();
    if (!data) return 0;

    const newCache = new Map<string, OpenRouterPricingEntry>();
    let count = 0;

    for (const model of data) {
      if (!this.isChatCompatible(model)) continue;
      if (!model.pricing) continue;

      const prompt = Number(model.pricing.prompt ?? 0);
      const completion = Number(model.pricing.completion ?? 0);
      if (!Number.isFinite(prompt) || !Number.isFinite(completion)) continue;
      if (prompt < 0 || completion < 0) continue;

      const displayName = this.extractDisplayName(model);
      const entry: OpenRouterPricingEntry = {
        input: prompt,
        output: completion,
        contextWindow: model.context_length ?? undefined,
        displayName: displayName || undefined,
      };

      // Store under full OpenRouter ID only (e.g. "anthropic/claude-opus-4-6")
      // All OpenRouter models are stored under provider "OpenRouter".
      newCache.set(model.id, entry);
      count++;
    }

    this.cache = newCache;
    this.lastFetchedAt = new Date();
    this.logger.log(`OpenRouter pricing cache loaded: ${count} models`);

    return count;
  }

  lookupPricing(modelId: string): OpenRouterPricingEntry | null {
    return this.cache.get(modelId) ?? null;
  }

  getAll(): ReadonlyMap<string, OpenRouterPricingEntry> {
    return this.cache;
  }

  getLastFetchedAt(): Date | null {
    return this.lastFetchedAt;
  }

  private async fetchOpenRouterModels(): Promise<OpenRouterModel[] | null> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
    try {
      const res = await fetch(OPENROUTER_API, { signal: controller.signal });
      if (!res.ok) {
        this.logger.error(`OpenRouter API returned ${res.status}`);
        return null;
      }
      const body = (await res.json()) as OpenRouterResponse;
      return body.data ?? [];
    } catch (err) {
      this.logger.error(`Failed to fetch OpenRouter models: ${err}`);
      return null;
    } finally {
      clearTimeout(timeout);
    }
  }

  extractDisplayName(model: OpenRouterModel): string {
    if (!model.name) return '';
    const colonIdx = model.name.indexOf(': ');
    if (colonIdx !== -1) return model.name.substring(colonIdx + 2);
    return model.name;
  }

  /**
   * Filter to models that accept text input and can produce text output.
   * Uses "includes text" (not "text-only") so multimodal models that
   * also produce text (e.g. GPT-4o) pass through.
   */
  isChatCompatible(model: OpenRouterModel): boolean {
    const inputModalities = model.architecture?.input_modalities?.map((m) => m.toLowerCase());
    if (inputModalities && inputModalities.length > 0 && !inputModalities.includes('text')) {
      return false;
    }

    const outputModalities = model.architecture?.output_modalities?.map((m) => m.toLowerCase());
    if (outputModalities && outputModalities.length > 0) {
      return outputModalities.includes('text');
    }

    return true;
  }
}

import { getMetadataArgsStorage } from 'typeorm';
import { AgentApiKey } from './agent-api-key.entity';
import { Tenant } from './tenant.entity';
import { Agent } from './agent.entity';

describe('AgentApiKey entity', () => {
  it('creates an instance with all fields', () => {
    const key = new AgentApiKey();
    key.id = 'aak-1';
    key.key = 'mnfst_abc123';
    key.key_hash = 'hash123';
    key.key_prefix = 'mnfst_abc1';
    key.label = 'default';
    key.tenant_id = 'tenant-1';
    key.agent_id = 'agent-1';
    key.is_active = true;
    key.expires_at = null;
    key.last_used_at = null;
    key.created_at = '2024-01-01T00:00:00Z';

    expect(key.id).toBe('aak-1');
    expect(key.key).toBe('mnfst_abc123');
    expect(key.key_hash).toBe('hash123');
    expect(key.key_prefix).toBe('mnfst_abc1');
    expect(key.label).toBe('default');
    expect(key.is_active).toBe(true);
    expect(key.expires_at).toBeNull();
    expect(key.last_used_at).toBeNull();
  });

  it('allows nullable fields to be null', () => {
    const key = new AgentApiKey();
    key.id = 'aak-2';
    key.key = null;
    key.label = null;
    key.expires_at = null;
    key.last_used_at = null;

    expect(key.key).toBeNull();
    expect(key.label).toBeNull();
    expect(key.expires_at).toBeNull();
    expect(key.last_used_at).toBeNull();
  });

  describe('TypeORM relation callbacks', () => {
    it('ManyToOne callback resolves to Tenant', () => {
      const relations = getMetadataArgsStorage().relations.filter((r) => r.target === AgentApiKey);
      const manyToOne = relations.find((r) => r.relationType === 'many-to-one');
      expect(manyToOne).toBeDefined();
      const resolved = (manyToOne!.type as () => unknown)();
      expect(resolved).toBe(Tenant);
    });

    it('OneToOne callback resolves to Agent with inverse side', () => {
      const relations = getMetadataArgsStorage().relations.filter((r) => r.target === AgentApiKey);
      const oneToOne = relations.find((r) => r.relationType === 'one-to-one');
      expect(oneToOne).toBeDefined();
      const resolved = (oneToOne!.type as () => unknown)();
      expect(resolved).toBe(Agent);

      // Invoke the inverse side callback
      const agent = new Agent();
      agent.apiKey = new AgentApiKey();
      const inverseFn = oneToOne!.inverseSideProperty as (obj: Agent) => unknown;
      expect(inverseFn(agent)).toBe(agent.apiKey);
    });
  });
});

import { getMetadataArgsStorage } from 'typeorm';
import { AgentEnabledProvider } from './agent-enabled-provider.entity';
import { Agent } from './agent.entity';
import { TenantProvider } from './tenant-provider.entity';

describe('AgentEnabledProvider entity', () => {
  it('creates an instance with both key columns', () => {
    const access = new AgentEnabledProvider();
    access.agent_id = 'agent-1';
    access.tenant_provider_id = 'provider-1';

    expect(access.agent_id).toBe('agent-1');
    expect(access.tenant_provider_id).toBe('provider-1');
  });

  it('declares cascade relations to agents and tenant providers', () => {
    const relations = getMetadataArgsStorage().relations.filter(
      (r) => r.target === AgentEnabledProvider,
    );

    const agentRelation = relations.find((r) => r.propertyName === 'agent');
    expect(agentRelation).toBeDefined();
    expect(agentRelation!.relationType).toBe('many-to-one');
    expect((agentRelation!.type as () => unknown)()).toBe(Agent);
    expect(agentRelation!.options.onDelete).toBe('CASCADE');

    const providerRelation = relations.find((r) => r.propertyName === 'tenantProvider');
    expect(providerRelation).toBeDefined();
    expect(providerRelation!.relationType).toBe('many-to-one');
    expect((providerRelation!.type as () => unknown)()).toBe(TenantProvider);
    expect(providerRelation!.options.onDelete).toBe('CASCADE');
  });
});

import { MCP_READ_SCOPE, MCP_WRITE_SCOPE, resolveMcpOperator, scopesFromClaims } from './mcp-auth';
import type { TenantCacheService } from '../common/services/tenant-cache.service';

function tenantCacheReturning(tenantId: string | null): TenantCacheService {
  return { resolve: jest.fn().mockResolvedValue(tenantId) } as unknown as TenantCacheService;
}

describe('scopesFromClaims', () => {
  it('splits the space-delimited scope claim', () => {
    expect([...scopesFromClaims({ scope: 'mcp:read mcp:write offline_access' })]).toEqual([
      MCP_READ_SCOPE,
      MCP_WRITE_SCOPE,
      'offline_access',
    ]);
  });

  it('treats a missing or non-string scope as no capabilities', () => {
    expect(scopesFromClaims({}).size).toBe(0);
    expect(scopesFromClaims({ scope: ['mcp:read'] }).size).toBe(0);
  });
});

describe('resolveMcpOperator', () => {
  it('maps the token subject to that user’s tenant', async () => {
    const cache = tenantCacheReturning('tenant-1');
    const operator = await resolveMcpOperator(cache, { sub: 'user-1', scope: MCP_READ_SCOPE });
    expect(operator).toEqual({
      userId: 'user-1',
      tenantId: 'tenant-1',
      scopes: new Set([MCP_READ_SCOPE]),
    });
    expect(cache.resolve).toHaveBeenCalledWith('user-1');
  });

  it('refuses a token with no subject', async () => {
    const cache = tenantCacheReturning('tenant-1');
    expect(await resolveMcpOperator(cache, { scope: MCP_READ_SCOPE })).toBeNull();
    expect(cache.resolve).not.toHaveBeenCalled();
  });

  it('refuses a user that has no tenant yet', async () => {
    const cache = tenantCacheReturning(null);
    expect(await resolveMcpOperator(cache, { sub: 'user-1' })).toBeNull();
  });
});

import { buildMcpServer } from './mcp-server.factory';
import { McpToolDeps } from './tool-deps';
import { McpOperator } from './mcp-auth';

jest.mock('../auth/auth.instance', () => ({ authOrigin: 'http://localhost:3001' }));

interface FakeServer {
  tools: string[];
  info: unknown;
  opts: unknown;
}
const mockInstances: FakeServer[] = [];

jest.mock('@modelcontextprotocol/server', () => ({
  McpServer: jest.fn().mockImplementation(function (
    this: FakeServer,
    info: unknown,
    opts: unknown,
  ) {
    this.info = info;
    this.opts = opts;
    this.tools = [];
    (this as unknown as { registerTool: (name: string) => void }).registerTool = (name: string) =>
      this.tools.push(name);
    mockInstances.push(this);
  }),
  createMcpHandler: jest.fn(),
}));

const deps = {} as McpToolDeps;

describe('buildMcpServer', () => {
  it('registers the full tool set for a read+write token', () => {
    const server = buildMcpServer(deps, {
      userId: 'u',
      tenantId: 't',
      scopes: new Set(['mcp:read', 'mcp:write']),
    }) as unknown as FakeServer;
    expect(server.tools).toContain('manifest_agent_create');
    expect(server.tools).toContain('manifest_provider_connect');
    expect(server.tools).toContain('manifest_routing_test');
    expect(server.tools).toContain('manifest_guide');
    expect(JSON.stringify(server.opts)).toContain('create, update, and delete');
  });

  // A per-POST server can never push a list-changed notification, and the bit
  // is what makes a client open a `subscriptions/listen` stream against this
  // endpoint. `McpServer` sets it by default once a tool is registered.
  it('does not advertise tools.listChanged on the stateless transport', () => {
    const server = buildMcpServer(deps, {
      userId: 'u',
      tenantId: 't',
      scopes: new Set(['mcp:read']),
    }) as unknown as FakeServer;
    expect(server.opts).toMatchObject({ capabilities: { tools: { listChanged: false } } });
  });

  it('hides write tools from a read-only token', () => {
    const server = buildMcpServer(deps, {
      userId: 'u',
      tenantId: 't',
      scopes: new Set(['mcp:read']),
    } satisfies McpOperator) as unknown as FakeServer;
    expect(server.tools).toContain('manifest_agent_list');
    expect(server.tools).not.toContain('manifest_agent_create');
    expect(JSON.stringify(server.opts)).toContain('read-only');
  });
});

import type { DataSource, EntityManager, Repository } from 'typeorm';
import { NotFoundException } from '@nestjs/common';
import { PlaygroundAgentService } from './playground-agent.service';
import type { Agent } from '../entities/agent.entity';
import type { TenantCacheService } from '../common/services/tenant-cache.service';
import type { TenantContext } from '../common/decorators/tenant-context.decorator';
import { PLAYGROUND_AGENT_NAME } from '../common/constants/playground.constants';

const TENANT_ID = 'tenant-abc';
const USER_ID = 'user-xyz';
const AGENT_ID = 'agent-sys-1';

/** A request context that already carries a resolved tenant. */
function ctxWithTenant(): TenantContext {
  return { tenantId: TENANT_ID, userId: USER_ID };
}

/** A request context for a fresh account: no tenant yet, only an authenticated user. */
function ctxNoTenant(): TenantContext {
  return { tenantId: null, userId: USER_ID };
}

/** A minimal Agent-shaped object that satisfies the service's return type. */
function makeAgent(overrides: Partial<Agent> = {}): Agent {
  return {
    id: AGENT_ID,
    name: PLAYGROUND_AGENT_NAME,
    display_name: PLAYGROUND_AGENT_NAME,
    is_playground: true,
    is_active: true,
    tenant_id: TENANT_ID,
    ...overrides,
  } as Agent;
}

interface Mocks {
  agentRepo: {
    findOne: jest.Mock;
  };
  tenantCache: {
    ensureForUser: jest.Mock;
    resolve: jest.Mock;
    invalidate: jest.Mock;
  };
  dataSource: {
    transaction: jest.Mock;
  };
}

/**
 * Build a mock EntityManager whose getRepository(Agent).insert and .query
 * can be configured per-test.
 */
function makeManager(
  insertFn: jest.Mock = jest.fn().mockResolvedValue(undefined),
  queryFn: jest.Mock = jest.fn().mockResolvedValue(undefined),
): EntityManager {
  return {
    getRepository: () => ({ insert: insertFn }),
    query: queryFn,
  } as unknown as EntityManager;
}

function buildService(mocks: Partial<Mocks> = {}): {
  service: PlaygroundAgentService;
  mocks: Mocks;
} {
  const full: Mocks = {
    agentRepo: {
      findOne: jest.fn().mockResolvedValue(null),
    },
    tenantCache: {
      ensureForUser: jest.fn().mockResolvedValue(TENANT_ID),
      resolve: jest.fn().mockResolvedValue(TENANT_ID),
      invalidate: jest.fn(),
    },
    dataSource: {
      // Default: runs the transaction callback with a stock manager (insert + query succeed).
      transaction: jest.fn().mockImplementation(async (cb: (m: EntityManager) => Promise<void>) => {
        await cb(makeManager());
      }),
    },
    ...mocks,
  };

  const service = new PlaygroundAgentService(
    full.agentRepo as unknown as Repository<Agent>,
    full.tenantCache as unknown as TenantCacheService,
    full.dataSource as unknown as DataSource,
  );

  return { service, mocks: full };
}

describe('PlaygroundAgentService.resolve', () => {
  describe('(a) tenant already on context — no tenant bootstrap', () => {
    it('does not call tenantCache.ensureForUser when ctx.tenantId is present', async () => {
      const existing = makeAgent();
      const { service, mocks } = buildService({
        agentRepo: { findOne: jest.fn().mockResolvedValue(existing) },
      });

      await service.resolve(ctxWithTenant());

      expect(mocks.tenantCache.ensureForUser).not.toHaveBeenCalled();
    });

    it('returns the existing agent when ctx carries a tenant and the agent exists', async () => {
      const existing = makeAgent();
      const { service } = buildService({
        agentRepo: { findOne: jest.fn().mockResolvedValue(existing) },
      });

      const result = await service.resolve(ctxWithTenant());
      expect(result).toBe(existing);
    });
  });

  describe('(a1) no tenant on context → bootstrap via tenantCache.ensureForUser', () => {
    it('calls tenantCache.ensureForUser(userId) and scopes the agent under the returned tenant', async () => {
      const ensureForUser = jest.fn().mockResolvedValue('bootstrapped-tenant');
      const { service } = buildService({
        tenantCache: { ensureForUser, resolve: jest.fn(), invalidate: jest.fn() },
      });

      const result = await service.resolve(ctxNoTenant());

      expect(ensureForUser).toHaveBeenCalledTimes(1);
      expect(ensureForUser).toHaveBeenCalledWith(USER_ID);
      // The agent should be created under the bootstrapped tenant id.
      expect(result.tenant_id).toBe('bootstrapped-tenant');
    });

    it('looks up the system agent under the bootstrapped tenant id', async () => {
      const ensureForUser = jest.fn().mockResolvedValue('bootstrapped-tenant');
      const { service, mocks } = buildService({
        tenantCache: { ensureForUser, resolve: jest.fn(), invalidate: jest.fn() },
      });

      await service.resolve(ctxNoTenant());

      expect(mocks.agentRepo.findOne).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ tenant_id: 'bootstrapped-tenant', is_playground: true }),
        }),
      );
    });
  });

  describe('(a2) no tenant and no user on context → not found', () => {
    it('throws NotFoundException without touching tenantCache', async () => {
      const ensureForUser = jest.fn();
      const { service } = buildService({
        tenantCache: { ensureForUser, resolve: jest.fn(), invalidate: jest.fn() },
      });

      await expect(service.resolve({ tenantId: null, userId: null })).rejects.toBeInstanceOf(
        NotFoundException,
      );
      expect(ensureForUser).not.toHaveBeenCalled();
    });
  });

  describe('(b) existing playground agent returned', () => {
    it('returns the existing agent without starting a transaction', async () => {
      const existing = makeAgent();
      const { service, mocks } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValue(existing),
        },
      });

      const result = await service.resolve(ctxWithTenant());

      expect(result).toBe(existing);
      expect(mocks.dataSource.transaction).not.toHaveBeenCalled();
    });

    it('queries agentRepo with the correct tenant_id, is_playground and deleted_at filters', async () => {
      const existing = makeAgent();
      const { service, mocks } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValue(existing),
        },
      });

      await service.resolve(ctxWithTenant());

      expect(mocks.agentRepo.findOne).toHaveBeenCalledWith(
        expect.objectContaining({
          where: expect.objectContaining({ tenant_id: TENANT_ID, is_playground: true }),
        }),
      );
    });
  });

  describe('(c) lazy-create path', () => {
    it('runs a transaction that inserts the agent and calls the provider-pool enable query', async () => {
      const insertFn = jest.fn().mockResolvedValue(undefined);
      const queryFn = jest.fn().mockResolvedValue(undefined);
      const manager = makeManager(insertFn, queryFn);

      const { service, mocks } = buildService({
        dataSource: {
          transaction: jest
            .fn()
            .mockImplementation(async (cb: (m: EntityManager) => Promise<void>) => {
              await cb(manager);
            }),
        },
      });

      const result = await service.resolve(ctxWithTenant());

      expect(mocks.dataSource.transaction).toHaveBeenCalledTimes(1);
      expect(insertFn).toHaveBeenCalledTimes(1);

      // The enable query must receive [agentId, tenantId].
      expect(queryFn).toHaveBeenCalledTimes(1);
      const [_sql, params] = queryFn.mock.calls[0] as [string, [string, string]];
      expect(params[0]).toBe(result.id);
      expect(params[1]).toBe(TENANT_ID);
    });

    it('returns a new agent with the correct fields (no DB re-fetch on success)', async () => {
      const { service, mocks } = buildService();

      const result = await service.resolve(ctxWithTenant());

      expect(result.name).toBe(PLAYGROUND_AGENT_NAME);
      expect(result.display_name).toBe(PLAYGROUND_AGENT_NAME);
      expect(result.is_playground).toBe(true);
      expect(result.is_active).toBe(true);
      expect(result.tenant_id).toBe(TENANT_ID);
      expect(typeof result.id).toBe('string');
      expect(result.id.length).toBeGreaterThan(0);

      // findOne called once (pre-insert check); no second call after success.
      expect(mocks.agentRepo.findOne).toHaveBeenCalledTimes(1);
    });
  });

  describe('(d) race: transaction throws → re-find returns a row', () => {
    it('returns the race winner row without running a second transaction', async () => {
      const raceWinner = makeAgent({ id: 'agent-winner' });
      const { service, mocks } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValueOnce(null).mockResolvedValueOnce(raceWinner),
        },
        dataSource: {
          transaction: jest
            .fn()
            .mockRejectedValue(new Error('duplicate key value violates unique')),
        },
      });

      const result = await service.resolve(ctxWithTenant());

      expect(result).toBe(raceWinner);
      expect(mocks.agentRepo.findOne).toHaveBeenCalledTimes(2);
      // Transaction was attempted once (and threw); no retry.
      expect(mocks.dataSource.transaction).toHaveBeenCalledTimes(1);
    });

    it('does not re-throw the transaction error when the race winner row is found', async () => {
      const raceWinner = makeAgent({ id: 'agent-winner' });
      const { service } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValueOnce(null).mockResolvedValueOnce(raceWinner),
        },
        dataSource: {
          transaction: jest.fn().mockRejectedValue(new Error('unique constraint')),
        },
      });

      await expect(service.resolve(ctxWithTenant())).resolves.toBe(raceWinner);
    });
  });

  describe('(e) transaction throws → re-find returns null', () => {
    it('re-throws the original DB error (not a race → surface the real failure)', async () => {
      const dbError = new Error('deadlock detected');
      const { service } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValue(null),
        },
        dataSource: {
          transaction: jest.fn().mockRejectedValue(dbError),
        },
      });

      await expect(service.resolve(ctxWithTenant())).rejects.toThrow('deadlock detected');
    });

    it('does not attempt a second transaction when the race re-find also returns null', async () => {
      const transactionFn = jest.fn().mockRejectedValue(new Error('duplicate key'));
      const { service } = buildService({
        agentRepo: {
          findOne: jest.fn().mockResolvedValue(null),
        },
        dataSource: {
          transaction: transactionFn,
        },
      });

      await expect(service.resolve(ctxWithTenant())).rejects.toThrow('duplicate key');
      expect(transactionFn).toHaveBeenCalledTimes(1);
    });
  });
});

import { Test, TestingModule } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { NotFoundException } from '@nestjs/common';
import { ResolveAgentService } from './routing-core/resolve-agent.service';
import { Agent } from '../entities/agent.entity';

describe('ResolveAgentService', () => {
  let service: ResolveAgentService;
  let mockFindOne: jest.Mock;

  beforeEach(async () => {
    mockFindOne = jest.fn();

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ResolveAgentService,
        {
          provide: getRepositoryToken(Agent),
          useValue: { findOne: mockFindOne },
        },
      ],
    }).compile();

    service = module.get<ResolveAgentService>(ResolveAgentService);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('throws NotFoundException when tenant id is null', async () => {
    await expect(service.resolve(null, 'my-agent')).rejects.toThrow(NotFoundException);
    await expect(service.resolve(null, 'my-agent')).rejects.toThrow('Tenant not found');
    expect(mockFindOne).not.toHaveBeenCalled();
  });

  it('throws NotFoundException when agent not found', async () => {
    mockFindOne.mockResolvedValue(null);

    await expect(service.resolve('tenant-123', 'nonexistent')).rejects.toThrow(NotFoundException);
    await expect(service.resolve('tenant-123', 'nonexistent')).rejects.toThrow(
      'Agent "nonexistent" not found',
    );
  });

  it('returns agent when found', async () => {
    const agent = { id: 'agent-1', name: 'my-agent', tenant_id: 'tenant-123' } as Agent;
    mockFindOne.mockResolvedValueOnce(agent);

    const result = await service.resolve('tenant-123', 'my-agent');

    expect(result).toEqual(agent);
    expect(mockFindOne).toHaveBeenCalledWith({
      where: { tenant_id: 'tenant-123', name: 'my-agent', deleted_at: expect.anything() },
    });
  });

  it('returns cached agent on second call without hitting DB again', async () => {
    const agent = { id: 'agent-1', name: 'my-agent', tenant_id: 'tenant-123' } as Agent;
    mockFindOne.mockResolvedValueOnce(agent);

    const first = await service.resolve('tenant-123', 'my-agent');
    const second = await service.resolve('tenant-123', 'my-agent');

    expect(first).toEqual(agent);
    expect(second).toEqual(agent);
    expect(mockFindOne).toHaveBeenCalledTimes(1);
  });

  it('evicts oldest entry when cache reaches MAX_ENTRIES', async () => {
    const cache = (service as any).cache as Map<string, unknown>;
    for (let i = 0; i < 5_000; i++) {
      cache.set(`t-${i}:a-${i}`, { agent: { id: `a-${i}` }, expiresAt: Date.now() + 120_000 });
    }
    expect(cache.size).toBe(5_000);

    const agent = { id: 'new-agent', name: 'new', tenant_id: 'tenant-123' } as Agent;
    mockFindOne.mockResolvedValueOnce(agent);

    await service.resolve('tenant-123', 'new');

    expect(cache.size).toBe(5_000);
    expect(cache.has('t-0:a-0')).toBe(false);
  });

  it('cache expires after TTL (120_000ms)', async () => {
    jest.useFakeTimers();
    const agentV1 = { id: 'agent-1', name: 'my-agent', tenant_id: 'tenant-123' } as Agent;
    const agentV2 = { id: 'agent-1', name: 'my-agent', tenant_id: 'tenant-123' } as Agent;
    mockFindOne.mockResolvedValueOnce(agentV1).mockResolvedValueOnce(agentV2);

    await service.resolve('tenant-123', 'my-agent');
    expect(mockFindOne).toHaveBeenCalledTimes(1);

    // Advance past TTL
    jest.advanceTimersByTime(120_001);

    const result = await service.resolve('tenant-123', 'my-agent');
    expect(result).toEqual(agentV2);
    expect(mockFindOne).toHaveBeenCalledTimes(2);
  });
});

