import { ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AgentKeyAuthGuard } from './agent-key-auth.guard';
import { hashKey } from '../../common/utils/hash.util';

// Edge-case coverage for AgentKeyAuthGuard that does not fit into the main
// spec file (which is already at the per-file size cap from CLAUDE.md). The
// primary spec is `agent-key-auth.guard.spec.ts`. These tests document
// behavior at the boundary of missing relations and DB failures during the
// dev-loopback seed-tenant lookup.

function makeContext(headers: Record<string, string | undefined>, ip = '203.0.113.1') {
  const request: Record<string, unknown> = { headers, ip, socket: { remoteAddress: ip } };
  return {
    req: request,
    ctx: {
      switchToHttp: () => ({
        getRequest: () => request,
      }),
    } as unknown as ExecutionContext,
  };
}

function createMockConfig(overrides: Record<string, string> = {}): ConfigService {
  const values: Record<string, string> = {
    'app.nodeEnv': 'test',
    ...overrides,
  };
  return {
    get: (key: string, fallback?: string) => values[key] ?? fallback,
  } as unknown as ConfigService;
}

describe('AgentKeyAuthGuard edge cases', () => {
  let guard: AgentKeyAuthGuard;
  let mockGetMany: jest.Mock;
  let mockGetOne: jest.Mock;
  let mockCreateQueryBuilder: jest.Mock;
  let mockExecute: jest.Mock;
  let mockFindOne: jest.Mock;
  let mockConfig: ConfigService;

  function buildMockRepo() {
    mockGetMany = jest.fn().mockResolvedValue([]);
    mockGetOne = jest.fn().mockResolvedValue(null);
    const mockSelectQb = {
      select: jest.fn().mockReturnThis(),
      leftJoin: jest.fn().mockReturnThis(),
      leftJoinAndSelect: jest.fn().mockReturnThis(),
      where: jest.fn().mockReturnThis(),
      andWhere: jest.fn().mockReturnThis(),
      getCount: jest.fn().mockResolvedValue(0),
      getMany: mockGetMany,
      getOne: mockGetOne,
    };
    mockExecute = jest.fn().mockResolvedValue({});
    const mockUpdateQb = {
      update: jest.fn().mockReturnThis(),
      set: jest.fn().mockImplementation((setObj) => {
        if (setObj) {
          for (const val of Object.values(setObj)) {
            if (typeof val === 'function') (val as () => unknown)();
          }
        }
        return mockUpdateQb;
      }),
      where: jest.fn().mockReturnThis(),
      execute: mockExecute,
    };
    mockCreateQueryBuilder = jest.fn().mockImplementation((alias?: string) => {
      return alias ? mockSelectQb : mockUpdateQb;
    });
    mockFindOne = jest.fn().mockResolvedValue(null);
    return {
      createQueryBuilder: mockCreateQueryBuilder,
      findOne: mockFindOne,
    } as never;
  }

  function createGuard(configOverrides: Record<string, string> = {}) {
    mockConfig = createMockConfig(configOverrides);
    const repo = buildMockRepo();
    const g = new AgentKeyAuthGuard(repo, mockConfig);
    g.clearCache();
    return g;
  }

  beforeEach(() => {
    guard = createGuard();
  });

  afterEach(() => {
    guard.onModuleDestroy();
  });

  describe('validateMnfstToken with broken relations', () => {
    // The candidate query left-joins agent + tenant. If either relation fails
    // to hydrate (race during a delete, foreign-key drift, missing JOIN
    // result), the guard now rejects with a clean UnauthorizedException (401)
    // instead of dereferencing null and surfacing a TypeError as a 500. These
    // tests pin that hardened behavior.
    it('rejects with 401 when keyRecord.agent is null', async () => {
      const token = '[REDACTED]';
      mockGetMany.mockResolvedValue([
        {
          id: 'key-no-agent',
          tenant_id: 'tenant-1',
          agent_id: 'agent-orphan',
          key_hash: hashKey(token),
          expires_at: null,
          agent: null,
          tenant: { owner_user_id: 'user-1' },
        },
      ]);

      const { ctx } = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(ctx)).rejects.toThrow(UnauthorizedException);
    });

    it('rejects with 401 when keyRecord.tenant is null', async () => {
      const token = '[REDACTED]';
      mockGetMany.mockResolvedValue([
        {
          id: 'key-no-tenant',
          tenant_id: 'tenant-orphan',
          agent_id: 'agent-1',
          key_hash: hashKey(token),
          expires_at: null,
          agent: { name: 'orphan-agent' },
          tenant: null,
        },
      ]);

      const { ctx } = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(ctx)).rejects.toThrow(UnauthorizedException);
    });

    it('rejects with 401 when both keyRecord.agent and keyRecord.tenant are null', async () => {
      const token = '[REDACTED]';
      mockGetMany.mockResolvedValue([
        {
          id: 'key-both-null',
          tenant_id: 'tenant-orphan',
          agent_id: 'agent-orphan',
          key_hash: hashKey(token),
          expires_at: null,
          agent: null,
          tenant: null,
        },
      ]);

      const { ctx } = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(ctx)).rejects.toThrow(UnauthorizedException);
    });

    it('remembers the rejection so an identical retry is served from the negative cache', async () => {
      const token = '[REDACTED]';
      mockGetMany.mockResolvedValue([
        {
          id: 'key-orphan-retry',
          tenant_id: 'tenant-1',
          agent_id: 'agent-orphan',
          key_hash: hashKey(token),
          expires_at: null,
          agent: null,
          tenant: { owner_user_id: 'user-1' },
        },
      ]);

      const first = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(first.ctx)).rejects.toThrow(UnauthorizedException);
      const second = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(second.ctx)).rejects.toThrow(UnauthorizedException);

      // The unhydrated-relation path calls rememberInvalid(), so the second
      // attempt short-circuits on the negative cache without a second DB hit.
      expect(mockGetMany).toHaveBeenCalledTimes(1);
    });

    it('does not cache a positive entry when agent is null (rejects before cache.set)', async () => {
      const token = '[REDACTED]';
      mockGetMany.mockResolvedValue([
        {
          id: 'key-uncached',
          tenant_id: 'tenant-1',
          agent_id: 'agent-1',
          key_hash: hashKey(token),
          expires_at: null,
          agent: null,
          tenant: { owner_user_id: 'user-1' },
        },
      ]);

      const { ctx } = makeContext({ authorization: `Bearer ${token}` });
      await expect(guard.canActivate(ctx)).rejects.toThrow(UnauthorizedException);

      // The guard rejects on the null relation before reaching cache.set, so
      // no positive entry lands in the cache — a poisoned entry can never be
      // served on a later request.
      const internalCache = (AgentKeyAuthGuard as unknown as { cache: Map<string, unknown> }).cache;
      expect(internalCache.size).toBe(0);
    });
  });

  describe('dev loopback seed-tenant lookup failure', () => {
    beforeEach(() => {
      guard.onModuleDestroy();
      guard = createGuard({ 'app.nodeEnv': 'development' });
    });

    // The seed-tenant lookup at lines 229-235 of the source has no try/catch.
    // If the DB connection drops or the query rejects, the rejection
    // propagates up through resolveDevContext -> handleDevLoopback ->
    // canActivate. The current fallback (`seedKey ?? findOne(...)`) only
    // covers the case where getOne() resolves to null — it does NOT cover
    // a rejected promise. This test pins that propagation so a future fix
    // (e.g. wrapping getOne in try/catch and falling back to findOne) has a
    // failing assertion to flip.
    it('propagates the error when seed-tenant getOne() rejects (no fallback today)', async () => {
      const dbError = new Error('Connection lost');
      mockGetOne.mockRejectedValue(dbError);
      mockFindOne.mockResolvedValue({
        tenant_id: 'dev-tenant',
        agent_id: 'dev-agent',
        agent: { name: 'demo-agent' },
        tenant: { owner_user_id: 'dev-user' },
      });

      const { ctx } = makeContext({ authorization: 'Bearer dev-no-auth' }, '127.0.0.1');
      await expect(guard.canActivate(ctx)).rejects.toThrow('Connection lost');

      // The findOne fallback is never reached because getOne rejected first.
      // If a future patch adds try/catch around getOne and falls through to
      // findOne, this assertion will fail loudly and force the test author
      // to update both this expectation and the one above.
      expect(mockFindOne).not.toHaveBeenCalled();
    });

    it('does not poison the devContext cache when seed-tenant getOne() rejects', async () => {
      mockGetOne.mockRejectedValue(new Error('Connection lost'));

      const { ctx } = makeContext({ authorization: 'Bearer dev-no-auth' }, '127.0.0.1');
      await expect(guard.canActivate(ctx)).rejects.toThrow('Connection lost');

      // devContext must remain unset so a subsequent successful call resolves
      // fresh. A poisoned cache would short-circuit future requests.
      const devContext = (
        guard as unknown as { devContext: { context: unknown; expiresAt: number } | null }
      ).devContext;
      expect(devContext).toBeNull();
    });

    it('falls back to findOne when seed-tenant getOne() resolves to null', async () => {
      // This covers the documented happy path of the `seedKey ?? findOne(...)`
      // fallback at line 237-242 — getOne returns null (seed tenant doesn't
      // exist in this DB), so the guard uses the first active key from
      // findOne. Pinned here because the rejection test above is the
      // pathological sibling — both branches need explicit assertions.
      mockGetOne.mockResolvedValue(null);
      mockFindOne.mockResolvedValue({
        tenant_id: 'first-tenant',
        agent_id: 'first-agent',
        agent: { name: 'first-agent-name' },
        tenant: { owner_user_id: 'first-user' },
      });

      const { ctx, req } = makeContext({ authorization: 'Bearer dev-no-auth' }, '127.0.0.1');
      const result = await guard.canActivate(ctx);

      expect(result).toBe(true);
      expect(req.ingestionContext).toEqual({
        tenantId: 'first-tenant',
        agentId: 'first-agent',
        agentName: 'first-agent-name',
        userId: 'first-user',
      });
      expect(mockGetOne).toHaveBeenCalledTimes(1);
      expect(mockFindOne).toHaveBeenCalledTimes(1);
    });
  });
});

import { SpecificityPenaltyService } from './specificity-penalty.service';
import type { Repository } from 'typeorm';
import type { AgentMessage } from '../../entities/agent-message.entity';

describe('SpecificityPenaltyService', () => {
  let service: SpecificityPenaltyService;
  let messageRepo: { createQueryBuilder: jest.Mock };

  function setRawMany(rows: { category: string; count: number }[]) {
    const qb = {
      select: jest.fn().mockReturnThis(),
      addSelect: jest.fn().mockReturnThis(),
      where: jest.fn().mockReturnThis(),
      andWhere: jest.fn().mockReturnThis(),
      groupBy: jest.fn().mockReturnThis(),
      getRawMany: jest.fn().mockResolvedValue(rows),
    };
    messageRepo.createQueryBuilder.mockReturnValueOnce(qb);
    return qb;
  }

  beforeEach(() => {
    messageRepo = { createQueryBuilder: jest.fn() };
    service = new SpecificityPenaltyService(messageRepo as unknown as Repository<AgentMessage>);
  });

  it('returns empty map when no agentId is supplied', async () => {
    const result = await service.getPenaltiesForAgent('');
    expect(result.size).toBe(0);
    expect(messageRepo.createQueryBuilder).not.toHaveBeenCalled();
  });

  it('converts flag counts into bounded per-category penalties', async () => {
    setRawMany([
      { category: 'web_browsing', count: 4 },
      { category: 'coding', count: 1 },
    ]);

    const penalties = await service.getPenaltiesForAgent('agent-1');

    // 4 * 0.75 = 3, capped at 3
    expect(penalties.get('web_browsing')).toBe(3);
    expect(penalties.get('coding')).toBeCloseTo(0.75);
  });

  it('drops rows whose category is not a known specificity category', async () => {
    setRawMany([{ category: 'mystery', count: 99 }]);

    const penalties = await service.getPenaltiesForAgent('agent-1');

    expect(penalties.size).toBe(0);
  });

  it('skips categories whose computed penalty is zero', async () => {
    setRawMany([{ category: 'web_browsing', count: 0 }]);

    const penalties = await service.getPenaltiesForAgent('agent-1');

    expect(penalties.size).toBe(0);
  });
});

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AgentMessage } from '../../entities/agent-message.entity';
import { SpecificityCategory, SPECIFICITY_CATEGORIES } from 'manifest-shared';

/**
 * Aggregates user-flagged miscategorizations (from the Messages log) into a
 * per-category score penalty applied at detection time. A category that
 * routes wrongly more than once starts losing weight; after enough flags it
 * requires an unambiguous anchor on the current turn to fire again.
 *
 * The flip-side writer is SpecificityFeedbackService in analytics — this
 * service is read-only and lives in routing-core to avoid a circular module
 * dependency with AnalyticsModule.
 */
@Injectable()
export class SpecificityPenaltyService {
  private static readonly PENALTY_PER_FLAG = 0.75;
  private static readonly PENALTY_CAP = 3;

  constructor(
    @InjectRepository(AgentMessage)
    private readonly messageRepo: Repository<AgentMessage>,
  ) {}

  async getPenaltiesForAgent(agentId: string): Promise<Map<SpecificityCategory, number>> {
    const penalties = new Map<SpecificityCategory, number>();
    if (!agentId) return penalties;

    const rows = await this.messageRepo
      .createQueryBuilder('m')
      .select('m.specificity_category', 'category')
      .addSelect('COUNT(*)::int', 'count')
      .where('m.specificity_miscategorized = true')
      .andWhere('m.specificity_category IS NOT NULL')
      .andWhere('m.agent_id = :agentId', { agentId })
      .groupBy('m.specificity_category')
      .getRawMany<{ category: string; count: number }>();

    for (const row of rows) {
      if (!(SPECIFICITY_CATEGORIES as readonly string[]).includes(row.category)) continue;
      const penalty = Math.min(
        row.count * SpecificityPenaltyService.PENALTY_PER_FLAG,
        SpecificityPenaltyService.PENALTY_CAP,
      );
      if (penalty > 0) {
        penalties.set(row.category as SpecificityCategory, penalty);
      }
    }
    return penalties;
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { randomUUID } from 'crypto';
import { DEFAULT_RESPONSE_MODE, DEFAULT_OUTPUT_MODALITY } from 'manifest-shared';
import type { AuthType, ModelRoute, ResponseMode } from 'manifest-shared';
import { SpecificityAssignment } from '../../entities/specificity-assignment.entity';
import { ModelDiscoveryService } from '../../model-discovery/model-discovery.service';
import { RoutingCacheService } from './routing-cache.service';
import { explicitRoute, readFallbackRoutes, unambiguousRoute, routeMatches } from './route-helpers';
import { assertStreamableResponseMode } from './response-mode-guard';

@Injectable()
export class SpecificityService {
  constructor(
    @InjectRepository(SpecificityAssignment)
    private readonly repo: Repository<SpecificityAssignment>,
    private readonly routingCache: RoutingCacheService,
    private readonly discoveryService: ModelDiscoveryService,
  ) {}

  async getAssignments(agentId: string): Promise<SpecificityAssignment[]> {
    const cached = this.routingCache.getSpecificity(agentId);
    if (cached) return cached;

    const rows = await this.repo.find({ where: { agent_id: agentId } });
    this.routingCache.setSpecificity(agentId, rows);
    return rows;
  }

  async getActiveAssignments(agentId: string): Promise<SpecificityAssignment[]> {
    const all = await this.getAssignments(agentId);
    return all.filter((a) => a.is_active);
  }

  async toggleCategory(
    agentId: string,
    category: string,
    active: boolean,
  ): Promise<SpecificityAssignment> {
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });

    if (existing) {
      existing.is_active = active;
      existing.updated_at = new Date().toISOString();
      await this.repo.save(existing);
      this.routingCache.invalidateAgent(agentId);
      return existing;
    }

    const record = Object.assign(new SpecificityAssignment(), {
      id: randomUUID(),
      agent_id: agentId,
      category,
      is_active: active,
      override_route: null,
      auto_assigned_route: null,
      fallback_routes: null,
      output_modality: DEFAULT_OUTPUT_MODALITY,
      response_mode: DEFAULT_RESPONSE_MODE,
    });

    try {
      await this.repo.insert(record);
    } catch (err) {
      // A concurrent request may have inserted the same (agent_id, category)
      // first, hitting the unique index. Re-read and adopt its row if present;
      // otherwise the failure is something else (FK violation, connection
      // error, …) and we rethrow rather than reporting a phantom success for a
      // row that was never persisted.
      const retry = await this.repo.findOne({ where: { agent_id: agentId, category } });
      if (retry) return this.toggleCategory(agentId, category, active);
      throw err;
    }
    this.routingCache.invalidateAgent(agentId);
    return record;
  }

  async setOverride(
    agentId: string,
    tenantId: string,
    category: string,
    model: string,
    provider?: string,
    authType?: AuthType,
    providerKeyLabel?: string,
  ): Promise<SpecificityAssignment> {
    const explicit = explicitRoute(model, provider, authType, providerKeyLabel);
    const route =
      explicit ??
      unambiguousRoute(
        model,
        await this.discoveryService.getModelsForAgent(tenantId, agentId),
        providerKeyLabel,
      );
    if (!route) {
      throw new BadRequestException(
        `Model "${model}" is offered by multiple providers — pass an explicit ` +
          `provider + authType so the route is unambiguous.`,
      );
    }
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });

    if (existing) {
      assertStreamableResponseMode(
        existing.response_mode,
        `task-specific tier "${category}"`,
        route,
        existing.fallback_routes,
      );
      existing.override_route = route;
      existing.is_active = true;
      existing.updated_at = new Date().toISOString();
      await this.repo.save(existing);
      this.routingCache.invalidateAgent(agentId);
      return existing;
    }

    const record = Object.assign(new SpecificityAssignment(), {
      id: randomUUID(),
      agent_id: agentId,
      category,
      is_active: true,
      override_route: route,
      auto_assigned_route: null,
      fallback_routes: null,
      output_modality: DEFAULT_OUTPUT_MODALITY,
      response_mode: DEFAULT_RESPONSE_MODE,
    });

    try {
      await this.repo.insert(record);
    } catch (err) {
      // A concurrent request may have inserted the same (agent_id, category)
      // first, hitting the unique index. Re-read and adopt its row if present;
      // otherwise the failure is something else (FK violation, connection
      // error, …) and we rethrow rather than reporting a phantom success for a
      // row that was never persisted.
      const retry = await this.repo.findOne({ where: { agent_id: agentId, category } });
      if (retry) {
        return this.setOverride(
          agentId,
          tenantId,
          category,
          model,
          provider,
          authType,
          providerKeyLabel,
        );
      }
      throw err;
    }
    this.routingCache.invalidateAgent(agentId);
    return record;
  }

  async setResponseMode(
    agentId: string,
    category: string,
    responseMode: ResponseMode,
  ): Promise<SpecificityAssignment> {
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });
    if (existing) {
      assertStreamableResponseMode(
        responseMode,
        `task-specific tier "${category}"`,
        existing.override_route,
        existing.fallback_routes,
      );
      existing.response_mode = responseMode;
      existing.updated_at = new Date().toISOString();
      await this.repo.save(existing);
      this.routingCache.invalidateAgent(agentId);
      return existing;
    }

    const record = Object.assign(new SpecificityAssignment(), {
      id: randomUUID(),
      agent_id: agentId,
      category,
      is_active: false,
      override_route: null,
      auto_assigned_route: null,
      fallback_routes: null,
      output_modality: DEFAULT_OUTPUT_MODALITY,
      response_mode: responseMode,
    });
    assertStreamableResponseMode(responseMode, `task-specific tier "${category}"`, null, null);
    await this.repo.insert(record);
    this.routingCache.invalidateAgent(agentId);
    return record;
  }

  async clearOverride(agentId: string, category: string): Promise<void> {
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });
    if (!existing) return;

    existing.override_route = null;
    existing.fallback_routes = null;
    assertStreamableResponseMode(
      existing.response_mode,
      `task-specific tier "${category}"`,
      null,
      null,
    );
    existing.updated_at = new Date().toISOString();
    await this.repo.save(existing);
    this.routingCache.invalidateAgent(agentId);
  }

  async setFallbacks(
    agentId: string,
    tenantId: string,
    category: string,
    models: string[],
    routes?: ModelRoute[],
  ): Promise<ModelRoute[]> {
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });
    if (!existing) return [];
    const fallbackRoutes = await this.buildFallbackRoutes(
      agentId,
      tenantId,
      models,
      routes,
      readFallbackRoutes(existing),
    );
    assertStreamableResponseMode(
      existing.response_mode,
      `task-specific tier "${category}"`,
      existing.override_route,
      fallbackRoutes,
    );
    existing.fallback_routes = fallbackRoutes;
    existing.updated_at = new Date().toISOString();
    await this.repo.save(existing);
    this.routingCache.invalidateAgent(agentId);
    return existing.fallback_routes ?? [];
  }

  async clearFallbacks(agentId: string, category: string): Promise<void> {
    const existing = await this.repo.findOne({ where: { agent_id: agentId, category } });
    if (!existing) return;
    assertStreamableResponseMode(
      existing.response_mode,
      `task-specific tier "${category}"`,
      existing.override_route,
      null,
    );
    existing.fallback_routes = null;
    existing.updated_at = new Date().toISOString();
    await this.repo.save(existing);
    this.routingCache.invalidateAgent(agentId);
  }

  async resetAll(agentId: string): Promise<void> {
    await this.repo.update(
      { agent_id: agentId },
      {
        is_active: false,
        override_route: null,
        fallback_routes: null,
        updated_at: new Date().toISOString(),
      },
    );
    this.routingCache.invalidateAgent(agentId);
  }

  /**
   * Mirror of {@link TierService.buildFallbackRoutes} — see that docblock for
   * the issue #1790 rationale on why this throws instead of returning null.
   */
  private async buildFallbackRoutes(
    agentId: string,
    tenantId: string,
    models: string[],
    routes?: ModelRoute[],
    storedRoutes?: ModelRoute[] | null,
  ): Promise<ModelRoute[] | null> {
    if (models.length === 0) return null;
    const available = await this.discoveryService.getModelsForAgent(tenantId, agentId);
    if (routes && routes.length === models.length) {
      const aligned = routes.every((r, i) => r.model === models[i]);
      const pool = [...(storedRoutes ?? [])];
      const validated =
        aligned &&
        routes.every((r) => {
          const kept = pool.findIndex((s) => routeMatches(s, r));
          if (kept >= 0) {
            pool.splice(kept, 1);
            return true;
          }
          return available.some(
            (m) =>
              m.id === r.model &&
              m.provider.toLowerCase() === r.provider.toLowerCase() &&
              m.authType === r.authType,
          );
        });
      if (validated) return routes;
    }
    const pool = [...(storedRoutes ?? [])];
    const resolved: ModelRoute[] = [];
    for (const m of models) {
      const kept = pool.findIndex((s) => s.model === m);
      if (kept >= 0) {
        resolved.push(pool[kept]);
        pool.splice(kept, 1);
        continue;
      }
      const route = unambiguousRoute(m, available);
      if (!route) {
        throw new BadRequestException(
          `Cannot resolve fallback model "${m}" to a single connected provider. ` +
            `Pass an explicit (provider, authType, model) route, or connect exactly one provider that offers this model.`,
        );
      }
      resolved.push(route);
    }
    return resolved;
  }
}

import { ProviderService } from '../../routing-core/provider.service';
import { mockSubscriptionCredentialLock } from '../__tests__/mock-subscription-lock';
import { ModelDiscoveryService } from '../../../model-discovery/model-discovery.service';
import { AnthropicOauthService } from './anthropic-oauth.service';
import {
  OAuthPendingFlowStore,
  type OAuthPendingFlowInput,
  type OAuthPendingFlowRecord,
} from '../core';

const originalFetch = global.fetch;

function mockResponse(status: number, body: unknown, text = ''): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
    text: async () => text || JSON.stringify(body),
  } as unknown as Response;
}

function createProviderService() {
  const upsertProvider = jest.fn().mockResolvedValue({ provider: { id: 'p1' } });
  const recalculateTiers = jest.fn().mockResolvedValue(undefined);
  const nextOAuthLabel = jest.fn().mockResolvedValue(undefined);
  const getFreshSubscriptionCredential = jest.fn().mockResolvedValue(null);
  return {
    svc: {
      upsertProvider,
      recalculateTiers,
      nextOAuthLabel,
      getFreshSubscriptionCredential,
      withSubscriptionCredentialLock: mockSubscriptionCredentialLock({
        getFreshSubscriptionCredential,
        upsertProvider,
      }),
    } as unknown as ProviderService,
    upsertProvider,
    recalculateTiers,
    nextOAuthLabel,
    getFreshSubscriptionCredential,
    withSubscriptionCredentialLock: mockSubscriptionCredentialLock({
      getFreshSubscriptionCredential,
      upsertProvider,
    }),
  };
}

function createDiscovery(): { svc: ModelDiscoveryService; discoverModels: jest.Mock } {
  const discoverModels = jest.fn().mockResolvedValue(undefined);
  return { svc: { discoverModels } as unknown as ModelDiscoveryService, discoverModels };
}

function createPendingStore() {
  const flows = new Map<string, OAuthPendingFlowRecord>();
  const key = (p: string, s: string) => `${p}:${s}`;
  const cleanup = () => {
    for (const [k, f] of flows) if (f.expiresAt < Date.now()) flows.delete(k);
  };
  const svc = {
    create: jest.fn(async (provider: string, input: OAuthPendingFlowInput, ttlMs: number) => {
      cleanup();
      for (const [k, f] of flows) {
        if (
          f.provider === provider &&
          f.agentId === input.agentId &&
          f.tenantId === input.tenantId
        ) {
          flows.delete(k);
        }
      }
      const record = { provider, ...input, expiresAt: Date.now() + ttlMs };
      flows.set(key(provider, input.state), record);
      return record;
    }),
    consume: jest.fn(async (provider: string, state: string, agentId: string, tenantId: string) => {
      const flow = flows.get(key(provider, state));
      if (!flow || flow.agentId !== agentId || flow.tenantId !== tenantId) return null;
      flows.delete(key(provider, state));
      return flow;
    }),
    findLatestForAgent: jest.fn(async (provider: string, agentId: string, tenantId: string) => {
      cleanup();
      for (const f of flows.values()) {
        if (f.provider === provider && f.agentId === agentId && f.tenantId === tenantId) return f;
      }
      return null;
    }),
    clear: jest.fn(async (provider: string, state: string) => {
      flows.delete(key(provider, state));
    }),
    count: jest.fn(async (provider: string) => {
      cleanup();
      let t = 0;
      for (const f of flows.values()) if (f.provider === provider) t += 1;
      return t;
    }),
  } as unknown as OAuthPendingFlowStore;
  return { svc, flows };
}

describe('AnthropicOauthService - security & edge cases', () => {
  let fetchMock: jest.Mock;
  let providerService: ReturnType<typeof createProviderService>;
  let discovery: ReturnType<typeof createDiscovery>;
  let pendingStore: ReturnType<typeof createPendingStore>;
  let svc: AnthropicOauthService;

  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2026-05-01T12:00:00Z'));
    fetchMock = jest.fn();
    global.fetch = fetchMock as unknown as typeof fetch;
    providerService = createProviderService();
    discovery = createDiscovery();
    pendingStore = createPendingStore();
    svc = new AnthropicOauthService(providerService.svc, discovery.svc, pendingStore.svc);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  afterAll(() => {
    global.fetch = originalFetch;
  });

  describe('exchangeCode tenant boundaries', () => {
    it('rejects exchange when state belongs to a different tenant', async () => {
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await expect(
        svc.exchangeCode(`code#${state}`, undefined, 'agent-1', 'tenant-2'),
      ).rejects.toThrow('Invalid or expired OAuth state');

      // Boundary check is enforced by the store, not the service.
      expect(pendingStore.svc.consume).toHaveBeenCalledWith(
        'anthropic',
        state,
        'agent-1',
        'tenant-2',
      );
      // Original owner's pending flow stays intact so user-1 can still finish.
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toEqual({ state });
      expect(fetchMock).not.toHaveBeenCalled();
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });

    it('rejects exchange when state belongs to a different agent', async () => {
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await expect(
        svc.exchangeCode(`code#${state}`, undefined, 'agent-2', 'tenant-1'),
      ).rejects.toThrow('Invalid or expired OAuth state');

      expect(pendingStore.svc.consume).toHaveBeenCalledWith(
        'anthropic',
        state,
        'agent-2',
        'tenant-1',
      );
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toEqual({ state });
      expect(fetchMock).not.toHaveBeenCalled();
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });

    it('rejects state reuse after first successful exchange', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a', refresh_token: 'r', expires_in: 3600 }),
      );
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await svc.exchangeCode(`first-code#${state}`, undefined, 'agent-1', 'tenant-1');
      expect(providerService.upsertProvider).toHaveBeenCalledTimes(1);
      await expect(svc.getPendingCount()).resolves.toBe(0);

      // Replaying the same state with a different code must fail — one-time token.
      await expect(
        svc.exchangeCode(`replayed-code#${state}`, undefined, 'agent-1', 'tenant-1'),
      ).rejects.toThrow('Invalid or expired OAuth state');
      expect(providerService.upsertProvider).toHaveBeenCalledTimes(1);
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });
  });

  describe('token endpoint error handling', () => {
    it('throws when the token endpoint returns malformed JSON', async () => {
      const badResponse = {
        ok: true,
        status: 200,
        json: async () => {
          throw new SyntaxError('Unexpected token < in JSON at position 0');
        },
        text: async () => '<html>oops</html>',
      } as unknown as Response;
      fetchMock.mockResolvedValue(badResponse);
      const logger = { error: jest.fn(), log: jest.fn(), warn: jest.fn() };
      (svc as unknown as { logger: typeof logger }).logger = logger;
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await expect(
        svc.exchangeCode(`c#${state}`, undefined, 'agent-1', 'tenant-1'),
      ).rejects.toBeInstanceOf(SyntaxError);

      // State is consumed before JSON parsing — no rollback path today.
      await expect(svc.getPendingCount()).resolves.toBe(0);
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });

    it('throws and logs when the token endpoint returns 503 Service Unavailable', async () => {
      fetchMock.mockResolvedValue(mockResponse(503, {}, 'Service Unavailable'));
      const logger = { error: jest.fn(), log: jest.fn(), warn: jest.fn() };
      (svc as unknown as { logger: typeof logger }).logger = logger;
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      const err = await svc
        .exchangeCode(`bad#${state}`, undefined, 'agent-1', 'tenant-1')
        .catch((e: Error) => e);
      // Generic Token exchange failed — no internal status text leakage.
      expect(err).toBeInstanceOf(Error);
      expect((err as Error).message).toBe('Token exchange failed');
      expect((err as Error).message).not.toContain('Service Unavailable');
      expect((err as Error).message).not.toContain('503');
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });

    it('propagates the network error when fetch() itself throws', async () => {
      fetchMock.mockRejectedValue(new Error('Network error'));
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await expect(
        svc.exchangeCode(`c#${state}`, undefined, 'agent-1', 'tenant-1'),
      ).rejects.toThrow('Network error');
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });
  });

  describe('unwrapToken expiry boundaries', () => {
    it('returns the cached access token at exactly 61s before expiry', async () => {
      // 61_000 > 60_000 → Date.now() < blob.e - 60_000 holds → return blob.t.
      const blob = JSON.stringify({ t: 'cached', r: 'rf', e: Date.now() + 61_000 });
      expect(await svc.unwrapToken(blob, 'agent-1', 'tenant-1')).toBe('cached');
      expect(fetchMock).not.toHaveBeenCalled();
    });

    it('refreshes at exactly 59s before expiry', async () => {
      // 59_000 < 60_000 → Date.now() < blob.e - 60_000 is FALSE → refresh path.
      const blob = JSON.stringify({ t: 'old', r: 'rf', e: Date.now() + 59_000 });
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'new', refresh_token: 'rf2', expires_in: 3600 }),
      );
      expect(await svc.unwrapToken(blob, 'agent-1', 'tenant-1')).toBe('new');
      expect(fetchMock).toHaveBeenCalledTimes(1);
    });

    it('refreshes when the token expires exactly now', async () => {
      const blob = JSON.stringify({ t: 'old', r: 'rf', e: Date.now() });
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'refreshed', refresh_token: 'rf2', expires_in: 3600 }),
      );
      expect(await svc.unwrapToken(blob, 'agent-1', 'tenant-1')).toBe('refreshed');
      expect(fetchMock).toHaveBeenCalledTimes(1);
      // New expiry is computed from Date.now() at the time of the refresh
      // response, not carried from the stale blob.
      const stored = providerService.upsertProvider.mock.calls[0][3] as string;
      expect(JSON.parse(stored).e).toBe(Date.now() + 3600 * 1000);
    });

    it('refresh updates the expiry from Date.now() rather than carrying the old e', async () => {
      // Pin a stale expiry 100s in the past so the refresh path runs.
      const staleExpiry = Date.now() - 100_000;
      const blob = JSON.stringify({ t: 'old', r: 'rf', e: staleExpiry });
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'fresh', refresh_token: 'rf2', expires_in: 1800 }),
      );
      await svc.unwrapToken(blob, 'agent-1', 'tenant-1');
      const stored = providerService.upsertProvider.mock.calls[0][3] as string;
      const parsed = JSON.parse(stored) as { t: string; r: string; e: number };
      expect(parsed.e).toBe(Date.now() + 1800 * 1000);
      expect(parsed.e).not.toBe(staleExpiry);
    });
  });

  describe('unwrapToken refresh-token fallbacks', () => {
    it('returns access_token when blob has empty refresh and is past the refresh threshold', async () => {
      // e = Date.now() + 30s puts us inside the 60s refresh window. With r='',
      // the service must short-circuit and return blob.t — no fetch attempt.
      const blob = JSON.stringify({ t: 'access', r: '', e: Date.now() + 30_000 });
      expect(await svc.unwrapToken(blob, 'agent-1', 'tenant-1')).toBe('access');
      expect(fetchMock).not.toHaveBeenCalled();
      expect(providerService.upsertProvider).not.toHaveBeenCalled();
    });

    it('rejects a JSON blob whose r field is null (type system enforces string)', async () => {
      // parseOAuthTokenBlob requires r: string, so r: null fails isOAuthTokenBlob
      // and the value is treated as a legacy paste token (returned as-is).
      const raw = JSON.stringify({ t: 'access', r: null, e: Date.now() + 30_000 });
      expect(await svc.unwrapToken(raw, 'agent-1', 'tenant-1')).toBe(raw);
      expect(fetchMock).not.toHaveBeenCalled();
    });

    it('rejects a JSON blob whose r field is missing entirely', async () => {
      // Missing r → not an OAuth blob → legacy paste fallback.
      const raw = JSON.stringify({ t: 'access', e: Date.now() + 30_000 });
      expect(await svc.unwrapToken(raw, 'agent-1', 'tenant-1')).toBe(raw);
      expect(fetchMock).not.toHaveBeenCalled();
    });
  });

  describe('refreshAccessToken expiry computation', () => {
    it('computes the new expiry from the refresh-response time, not the prior token', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a2', refresh_token: 'r2', expires_in: 1800 }),
      );
      const before = Date.now();
      const blob = await svc.refreshAccessToken('old-refresh');
      expect(blob.e).toBe(before + 1800 * 1000);
    });
  });
});

import { ProviderService } from '../../routing-core/provider.service';
import { mockSubscriptionCredentialLock } from '../__tests__/mock-subscription-lock';
import { ModelDiscoveryService } from '../../../model-discovery/model-discovery.service';
import {
  AnthropicOauthExchangeError,
  AnthropicOauthService,
  splitAnthropicAuthPayload,
} from './anthropic-oauth.service';
import { ANTHROPIC_OAUTH } from './anthropic-oauth.config';
import {
  OAuthPendingFlowStore,
  type OAuthPendingFlowInput,
  type OAuthPendingFlowRecord,
} from '../core';

const originalFetch = global.fetch;

function mockResponse(status: number, body: unknown, text = ''): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
    text: async () => text || JSON.stringify(body),
  } as unknown as Response;
}

function createProviderService() {
  const upsertProvider = jest.fn().mockResolvedValue({ provider: { id: 'p1' } });
  const recalculateTiers = jest.fn().mockResolvedValue(undefined);
  const recalculateTiersForTenant = jest.fn().mockResolvedValue(undefined);
  const nextOAuthLabel = jest.fn().mockResolvedValue(undefined);
  const getFreshSubscriptionCredential = jest.fn().mockResolvedValue(null);
  return {
    svc: {
      upsertProvider,
      recalculateTiers,
      recalculateTiersForTenant,
      nextOAuthLabel,
      getFreshSubscriptionCredential,
      withSubscriptionCredentialLock: mockSubscriptionCredentialLock({
        getFreshSubscriptionCredential,
        upsertProvider,
      }),
    } as unknown as ProviderService,
    upsertProvider,
    recalculateTiers,
    recalculateTiersForTenant,
    nextOAuthLabel,
    getFreshSubscriptionCredential,
    withSubscriptionCredentialLock: mockSubscriptionCredentialLock({
      getFreshSubscriptionCredential,
      upsertProvider,
    }),
  };
}

function createDiscovery(): { svc: ModelDiscoveryService; discoverModels: jest.Mock } {
  const discoverModels = jest.fn().mockResolvedValue(undefined);
  return { svc: { discoverModels } as unknown as ModelDiscoveryService, discoverModels };
}

function createPendingStore() {
  const flows = new Map<string, OAuthPendingFlowRecord>();
  const key = (provider: string, state: string) => `${provider}:${state}`;
  const cleanup = () => {
    for (const [flowKey, flow] of flows) {
      if (flow.expiresAt < Date.now()) flows.delete(flowKey);
    }
  };
  const svc = {
    create: jest.fn(async (provider: string, input: OAuthPendingFlowInput, ttlMs: number) => {
      cleanup();
      for (const [flowKey, flow] of flows) {
        if (
          flow.provider === provider &&
          flow.agentId === input.agentId &&
          flow.tenantId === input.tenantId
        ) {
          flows.delete(flowKey);
        }
      }
      const record = { provider, ...input, expiresAt: Date.now() + ttlMs };
      flows.set(key(provider, input.state), record);
      return record;
    }),
    consume: jest.fn(async (provider: string, state: string, agentId: string, tenantId: string) => {
      const flow = flows.get(key(provider, state));
      if (!flow || flow.agentId !== agentId || flow.tenantId !== tenantId) return null;
      flows.delete(key(provider, state));
      return flow;
    }),
    findLatestForAgent: jest.fn(async (provider: string, agentId: string, tenantId: string) => {
      cleanup();
      for (const flow of flows.values()) {
        if (flow.provider === provider && flow.agentId === agentId && flow.tenantId === tenantId) {
          return flow;
        }
      }
      return null;
    }),
    clear: jest.fn(async (provider: string, state: string) => {
      flows.delete(key(provider, state));
    }),
    count: jest.fn(async (provider: string) => {
      cleanup();
      let total = 0;
      for (const flow of flows.values()) {
        if (flow.provider === provider) total += 1;
      }
      return total;
    }),
  } as unknown as OAuthPendingFlowStore;
  return { svc, flows };
}

describe('splitAnthropicAuthPayload', () => {
  it('returns the bare code when no state suffix is present', () => {
    expect(splitAnthropicAuthPayload('abc123')).toEqual({ code: 'abc123' });
  });

  it('splits `<code>#<state>` into separate parts', () => {
    expect(splitAnthropicAuthPayload('abc#xyz')).toEqual({ code: 'abc', state: 'xyz' });
  });

  it('treats a trailing # as no state', () => {
    expect(splitAnthropicAuthPayload('abc#')).toEqual({ code: 'abc', state: undefined });
  });

  it('trims surrounding whitespace from pasted input', () => {
    expect(splitAnthropicAuthPayload('  abc#xyz  ')).toEqual({ code: 'abc', state: 'xyz' });
  });
});

describe('AnthropicOauthService', () => {
  let fetchMock: jest.Mock;
  let providerService: ReturnType<typeof createProviderService>;
  let discovery: ReturnType<typeof createDiscovery>;
  let pendingStore: ReturnType<typeof createPendingStore>;
  let svc: AnthropicOauthService;

  beforeEach(() => {
    jest.useFakeTimers();
    jest.setSystemTime(new Date('2026-05-01T12:00:00Z'));
    fetchMock = jest.fn();
    global.fetch = fetchMock as unknown as typeof fetch;
    providerService = createProviderService();
    discovery = createDiscovery();
    pendingStore = createPendingStore();
    svc = new AnthropicOauthService(providerService.svc, discovery.svc, pendingStore.svc);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  afterAll(() => {
    global.fetch = originalFetch;
  });

  describe('generateAuthorizationUrl', () => {
    it('builds a Claude.ai authorize URL with PKCE S256 challenge and tracks pending state', async () => {
      const { url, state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');
      const parsed = new URL(url);
      expect(parsed.origin + parsed.pathname).toBe(ANTHROPIC_OAUTH.AUTHORIZE_URL);
      expect(parsed.searchParams.get('client_id')).toBe(ANTHROPIC_OAUTH.CLIENT_ID);
      expect(parsed.searchParams.get('response_type')).toBe('code');
      expect(parsed.searchParams.get('redirect_uri')).toBe(ANTHROPIC_OAUTH.REDIRECT_URI);
      expect(parsed.searchParams.get('scope')).toBe(ANTHROPIC_OAUTH.SCOPE);
      expect(parsed.searchParams.get('code_challenge_method')).toBe('S256');
      expect(parsed.searchParams.get('code_challenge')?.length).toBeGreaterThan(0);
      expect(parsed.searchParams.get('state')).toBe(state);
      expect(pendingStore.svc.create).toHaveBeenCalledWith(
        'anthropic',
        expect.objectContaining({ state, verifier: state }),
        ANTHROPIC_OAUTH.STATE_TTL_MS,
      );
      await expect(svc.getPendingCount()).resolves.toBe(1);
    });
  });

  describe('exchangeCode', () => {
    it('rejects when no code is supplied', async () => {
      await expect(svc.exchangeCode('', 'state', 'agent-1', 'tenant-1')).rejects.toThrow(
        'Missing authorization code',
      );
    });

    it('rejects when no state is supplied', async () => {
      await expect(svc.exchangeCode('code', undefined, 'agent-1', 'tenant-1')).rejects.toThrow(
        'Missing OAuth state',
      );
    });

    it('rejects unknown states', async () => {
      await expect(
        svc.exchangeCode('code#bogus', undefined, 'agent-1', 'tenant-1'),
      ).rejects.toThrow('Invalid or expired OAuth state');
    });

    it('rejects (and purges) expired states', async () => {
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      jest.advanceTimersByTime(ANTHROPIC_OAUTH.STATE_TTL_MS + 1);
      await expect(svc.exchangeCode(`code#${state}`, undefined, 'a', 't')).rejects.toThrow(
        'OAuth state expired',
      );
      await expect(svc.getPendingCount()).resolves.toBe(0);
    });

    it('exchanges a valid code, stores the blob, and triggers model discovery', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, {
          access_token: 'access-1',
          refresh_token: 'refresh-1',
          expires_in: 3600,
        }),
      );
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await svc.exchangeCode(`auth-code#${state}`, undefined, 'agent-1', 'tenant-1');

      expect(fetchMock).toHaveBeenCalledTimes(1);
      const [tokenUrl, init] = fetchMock.mock.calls[0];
      expect(tokenUrl).toBe(ANTHROPIC_OAUTH.TOKEN_URL);
      expect(new URL(tokenUrl).origin).toBe('https://api.anthropic.com');
      expect(init.headers).toEqual({
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'User-Agent': 'anthropic',
      });
      const body = JSON.parse(init.body);
      expect(body.grant_type).toBe('authorization_code');
      expect(body.code).toBe('auth-code');
      expect(body.state).toBe(state);
      expect(body.code_verifier).toBe(state);

      expect(providerService.upsertProvider).toHaveBeenCalledWith(
        'agent-1',
        'tenant-1',
        'anthropic',
        expect.stringContaining('"t":"access-1"'),
        'subscription',
        undefined,
        undefined,
        undefined,
      );
      expect(discovery.discoverModels).toHaveBeenCalled();
      expect(providerService.recalculateTiers).not.toHaveBeenCalled();
      expect(providerService.recalculateTiersForTenant).not.toHaveBeenCalled();
      await expect(svc.getPendingCount()).resolves.toBe(0);
    });

    it('does not route agents after discovery when the provider row is new', async () => {
      providerService.upsertProvider.mockResolvedValueOnce({ provider: { id: 'p1' }, isNew: true });
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a', refresh_token: 'r', expires_in: 3600 }),
      );
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await svc.exchangeCode(`auth-code#${state}`, undefined, 'agent-1', 'tenant-1');

      expect(discovery.discoverModels).toHaveBeenCalledWith({ id: 'p1' });
      expect(providerService.recalculateTiersForTenant).not.toHaveBeenCalled();
      expect(providerService.recalculateTiers).not.toHaveBeenCalled();
    });

    it('accepts the code and state passed separately', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a', refresh_token: 'r', expires_in: 60 }),
      );
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      await svc.exchangeCode('plain-code', state, 'a', 't');
      expect(providerService.upsertProvider).toHaveBeenCalled();
    });

    it('uses the next OAuth label when adding another Anthropic account', async () => {
      providerService.nextOAuthLabel.mockResolvedValue('Key 2');
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a2', refresh_token: 'r2', expires_in: 60 }),
      );
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');

      await svc.exchangeCode(`second-code#${state}`, undefined, 'agent-1', 'tenant-1');

      expect(providerService.nextOAuthLabel).toHaveBeenCalledWith('tenant-1', 'anthropic');
      expect(providerService.upsertProvider).toHaveBeenCalledWith(
        'agent-1',
        'tenant-1',
        'anthropic',
        expect.stringContaining('"t":"a2"'),
        'subscription',
        undefined,
        'Key 2',
        undefined,
      );
    });

    it('falls back to the latest pending state when the client posts a bare code', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a', refresh_token: 'r', expires_in: 60 }),
      );
      const { state } = await svc.generateAuthorizationUrl('a', 't');

      await svc.exchangeCode('plain-code', undefined, 'a', 't');

      const [, init] = fetchMock.mock.calls[0];
      expect(JSON.parse(init.body).state).toBe(state);
      expect(providerService.upsertProvider).toHaveBeenCalled();
    });

    it('throws when the token endpoint returns an error', async () => {
      fetchMock.mockResolvedValue(mockResponse(400, {}, 'invalid_grant'));
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      const logger = { error: jest.fn(), log: jest.fn(), warn: jest.fn() };
      (svc as unknown as { logger: typeof logger }).logger = logger;

      await expect(svc.exchangeCode(`bad#${state}`, undefined, 'a', 't')).rejects.toThrow(
        'Token exchange failed',
      );
      expect(logger.error).toHaveBeenCalledWith(
        expect.stringContaining('"stateMatchesCodeVerifier":true'),
      );
    });

    it('preserves Anthropic token endpoint rate limits as rate-limit errors', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(400, {
          error: {
            type: 'rate_limit_error',
            message: 'Rate limited. Please try again later.',
          },
        }),
      );
      const { state } = await svc.generateAuthorizationUrl('a', 't');

      await expect(svc.exchangeCode(`bad#${state}`, undefined, 'a', 't')).rejects.toMatchObject({
        message:
          'Anthropic rate-limited the OAuth token exchange. Please wait a minute, then sign in again.',
        status: 429,
      } satisfies Partial<AnthropicOauthExchangeError>);
    });

    it('falls back to state when the pending verifier is missing', async () => {
      fetchMock.mockResolvedValue(mockResponse(400, {}, 'invalid_request'));
      const logger = { error: jest.fn(), log: jest.fn(), warn: jest.fn() };
      (svc as unknown as { logger: typeof logger }).logger = logger;
      jest.spyOn(pendingStore.svc, 'consume').mockResolvedValue({
        provider: 'anthropic',
        state: 'state-1',
        verifier: undefined as unknown as string,
        agentId: 'agent-1',
        tenantId: 'tenant-1',
        expiresAt: Date.now() + 60_000,
      });

      await expect(
        svc.exchangeCode('bad#state-1', undefined, 'agent-1', 'tenant-1'),
      ).rejects.toThrow('Token exchange failed');

      const [, init] = fetchMock.mock.calls[0];
      expect(JSON.parse(init.body).code_verifier).toBe('state-1');
      expect(logger.error).toHaveBeenCalledWith(
        expect.stringContaining('"stateMatchesCodeVerifier":true'),
      );
    });

    it('stores an empty refresh token when Anthropic omits one in the response', async () => {
      // No refresh_token field — defensive fallback exercises the `?? ''`.
      fetchMock.mockResolvedValue(mockResponse(200, { access_token: 'a', expires_in: 60 }));
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      await svc.exchangeCode(`c#${state}`, undefined, 'a', 't');
      const stored = providerService.upsertProvider.mock.calls[0][3] as string;
      expect(JSON.parse(stored).r).toBe('');
    });

    it('swallows discovery errors so the OAuth save is not rolled back', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a', refresh_token: 'r', expires_in: 60 }),
      );
      discovery.discoverModels.mockRejectedValue(new Error('boom'));
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      await expect(svc.exchangeCode(`c#${state}`, undefined, 'a', 't')).resolves.toBeUndefined();
      expect(providerService.upsertProvider).toHaveBeenCalled();
    });
  });

  describe('refreshAccessToken', () => {
    it('returns a fresh blob with a new expiry', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'a2', refresh_token: 'r2', expires_in: 1800 }),
      );
      const blob = await svc.refreshAccessToken('old-refresh');
      expect(blob).toEqual({ t: 'a2', r: 'r2', e: Date.now() + 1800 * 1000 });
      expect(fetchMock.mock.calls[0][1].headers).toEqual({
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'User-Agent': 'anthropic',
      });
    });

    it('retains the old refresh token when the server omits a new one', async () => {
      fetchMock.mockResolvedValue(mockResponse(200, { access_token: 'a2', expires_in: 60 }));
      const blob = await svc.refreshAccessToken('old');
      expect(blob.r).toBe('old');
    });

    it('throws when the refresh endpoint returns a non-2xx status', async () => {
      fetchMock.mockResolvedValue(mockResponse(400, {}));
      await expect(svc.refreshAccessToken('r')).rejects.toThrow('Token refresh failed');
    });
  });

  describe('unwrapToken', () => {
    it('returns the raw value when it is not an OAuth blob (legacy setup-token)', async () => {
      expect(await svc.unwrapToken('sk-ant-oat01-legacy', 'a', 't')).toBe('sk-ant-oat01-legacy');
    });

    it('returns null when given an empty string', async () => {
      expect(await svc.unwrapToken('', 'a', 't')).toBeNull();
    });

    it('returns the cached access token when it is still valid', async () => {
      const blob = JSON.stringify({ t: 'access', r: 'refresh', e: Date.now() + 10 * 60_000 });
      expect(await svc.unwrapToken(blob, 'a', 't')).toBe('access');
      expect(fetchMock).not.toHaveBeenCalled();
    });

    it('refreshes and persists a fresh blob when the token is near expiry', async () => {
      const blob = JSON.stringify({ t: 'old', r: 'rf', e: Date.now() + 30_000 });
      fetchMock.mockResolvedValue(
        mockResponse(200, { access_token: 'new', refresh_token: 'rf2', expires_in: 3600 }),
      );
      const token = await svc.unwrapToken(blob, 'agent-1', 'tenant-1', 'Work');
      expect(token).toBe('new');
      expect(providerService.upsertProvider).toHaveBeenCalledWith(
        null,
        'tenant-1',
        'anthropic',
        expect.stringContaining('"t":"new"'),
        'subscription',
        undefined,
        'Work',
      );
    });

    it('returns the access token unchanged when the blob has no refresh token', async () => {
      const blob = JSON.stringify({ t: 'access', r: '', e: Date.now() + 30_000 });
      expect(await svc.unwrapToken(blob, 'a', 't')).toBe('access');
      expect(fetchMock).not.toHaveBeenCalled();
    });

    it('returns null when the refresh call fails', async () => {
      const blob = JSON.stringify({ t: 'old', r: 'rf', e: Date.now() + 1_000 });
      fetchMock.mockRejectedValue(new Error('network'));
      expect(await svc.unwrapToken(blob, 'a', 't')).toBeNull();
    });
  });

  describe('clearPendingState', () => {
    it('removes a known pending state', async () => {
      const { state } = await svc.generateAuthorizationUrl('a', 't');
      await expect(svc.getPendingCount()).resolves.toBe(1);
      await svc.clearPendingState(state);
      await expect(svc.getPendingCount()).resolves.toBe(0);
    });
  });

  describe('findPendingForAgent', () => {
    it('returns the active state when one exists for the agent and user', async () => {
      const { state } = await svc.generateAuthorizationUrl('agent-1', 'tenant-1');
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toEqual({ state });
    });

    it('returns null when no flow is pending for the agent', async () => {
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toBeNull();
    });

    it('skips entries belonging to other agents', async () => {
      await svc.generateAuthorizationUrl('other-agent', 'tenant-1');
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toBeNull();
    });

    it('skips entries belonging to other users', async () => {
      await svc.generateAuthorizationUrl('agent-1', 'other-tenant');
      await expect(svc.findPendingForAgent('agent-1', 'tenant-1')).resolves.toBeNull();
    });
  });
});

import { CopilotDeviceAuthService } from './copilot-device-auth.service';

const originalFetch = global.fetch;

function mockResponse(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
  } as unknown as Response;
}

describe('CopilotDeviceAuthService', () => {
  let svc: CopilotDeviceAuthService;
  let fetchMock: jest.Mock;

  beforeEach(() => {
    fetchMock = jest.fn();
    global.fetch = fetchMock as unknown as typeof fetch;
    svc = new CopilotDeviceAuthService();
  });

  afterAll(() => {
    global.fetch = originalFetch;
  });

  describe('requestDeviceCode', () => {
    it('POSTs to the GitHub device endpoint with the hard-coded client id and read:user scope', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, {
          device_code: 'dev-abc',
          user_code: 'USER-CODE',
          verification_uri: 'https://github.com/login/device',
          expires_in: 900,
          interval: 5,
        }),
      );

      const out = await svc.requestDeviceCode();

      expect(out.device_code).toBe('dev-abc');
      expect(out.user_code).toBe('USER-CODE');
      expect(fetchMock).toHaveBeenCalledTimes(1);
      const [url, init] = fetchMock.mock.calls[0];
      expect(url).toBe('https://github.com/login/device/code');
      expect(init.method).toBe('POST');
      expect(init.headers).toMatchObject({
        Accept: 'application/json',
        'Content-Type': 'application/x-www-form-urlencoded',
      });
      const params = new URLSearchParams(init.body.toString());
      expect(params.get('client_id')).toBe('Iv1.b507a08c87ecfe98');
      expect(params.get('scope')).toBe('read:user');
    });

    it('throws when GitHub returns a non-2xx status', async () => {
      fetchMock.mockResolvedValue(mockResponse(503, {}));
      await expect(svc.requestDeviceCode()).rejects.toThrow(
        'GitHub device code request failed: 503',
      );
    });

    it('throws when GitHub returns a malformed payload (missing device_code or user_code)', async () => {
      fetchMock.mockResolvedValue(
        mockResponse(200, { verification_uri: 'x', expires_in: 1, interval: 1 }),
      );
      await expect(svc.requestDeviceCode()).rejects.toThrow(
        'Invalid device code response from GitHub',
      );
    });
  });

  describe('pollForToken', () => {
    it('POSTs to the GitHub token endpoint with the device grant type', async () => {
      fetchMock.mockResolvedValue(mockResponse(200, { access_token: 'ghs_abc' }));
      const out = await svc.pollForToken('dev-abc');
      expect(out).toEqual({ status: 'complete', token: 'ghs_abc' });

      const [url, init] = fetchMock.mock.calls[0];
      expect(url).toBe('https://github.com/login/oauth/access_token');
      const params = new URLSearchParams(init.body.toString());
      expect(params.get('client_id')).toBe('Iv1.b507a08c87ecfe98');
      expect(params.get('device_code')).toBe('dev-abc');
      expect(params.get('grant_type')).toBe('urn:ietf:params:oauth:grant-type:device_code');
    });

    it('maps authorization_pending → pending', async () => {
      fetchMock.mockResolvedValue(mockResponse(200, { error: 'authorization_pending' }));
      expect(await svc.pollForToken('d')).toEqual({ status: 'pending' });
    });

    it('maps slow_down, expired_token, and access_denied to their own statuses', async () => {
      fetchMock.mockResolvedValueOnce(mockResponse(200, { error: 'slow_down' }));
      expect((await svc.pollForToken('d')).status).toBe('slow_down');

      fetchMock.mockResolvedValueOnce(mockResponse(200, { error: 'expired_token' }));
      expect((await svc.pollForToken('d')).status).toBe('expired');

      fetchMock.mockResolvedValueOnce(mockResponse(200, { error: 'access_denied' }));
      expect((await svc.pollForToken('d')).status).toBe('denied');
    });

    it('falls back to pending for unrecognised responses and logs a warning', async () => {
      const warn = jest.spyOn((svc as unknown as { logger: { warn: () => void } }).logger, 'warn');
      fetchMock.mockResolvedValue(mockResponse(200, { error: 'something_new' }));
      expect(await svc.pollForToken('d')).toEqual({ status: 'pending' });
      expect(warn).toHaveBeenCalledWith(expect.stringContaining('Unexpected GitHub poll response'));
    });

    it('throws when GitHub returns a non-2xx status', async () => {
      fetchMock.mockResolvedValue(mockResponse(500, {}));
      await expect(svc.pollForToken('d')).rejects.toThrow('GitHub token poll failed: 500');
    });
  });
});

'use strict';

// Run with: node --test scripts/   (Node's built-in test runner; no jest needed)
const { test } = require('node:test');
const assert = require('node:assert/strict');

const {
  RAILWAY_GRAPHQL_ENDPOINT,
  HTTP_LOGS_QUERY,
  statusClass,
  getStatus,
  getPath,
  aggregate,
  formatReport,
  parseArgs,
  fetchHttpLogs,
} = require('./railway-http-logs');

test('statusClass buckets each status into its class', () => {
  assert.equal(statusClass(204), '2xx');
  assert.equal(statusClass(301), '3xx');
  assert.equal(statusClass(404), '4xx');
  assert.equal(statusClass(503), '5xx');
  assert.equal(statusClass(100), 'other');
  assert.equal(statusClass(700), 'other');
  assert.equal(statusClass('nope'), 'other');
});

test('getStatus tolerates httpStatus / status / statusCode variants', () => {
  assert.equal(getStatus({ httpStatus: 401 }), 401);
  assert.equal(getStatus({ status: 404 }), 404);
  assert.equal(getStatus({ statusCode: 429 }), 429);
  assert.ok(Number.isNaN(getStatus({})));
});

test('getPath strips the query string and tolerates path / url variants', () => {
  assert.equal(getPath({ path: '/v1/chat/completions' }), '/v1/chat/completions');
  assert.equal(getPath({ path: '/api/v1/messages?page=2&range=30d' }), '/api/v1/messages');
  assert.equal(getPath({ url: '/assets/app.js?v=abc' }), '/assets/app.js');
  assert.equal(getPath({}), '');
});

test('aggregate counts by status, by class, and by (status, path) sorted desc', () => {
  const records = [
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 404, path: '/wp-login.php' },
    { httpStatus: 302, path: '/api/auth/sign-in/social' },
    { httpStatus: 200, path: '/api/v1/overview' },
  ];
  const agg = aggregate(records);

  assert.equal(agg.total, 6);
  assert.equal(agg.byStatus['401'], 3);
  assert.equal(agg.byClass['4xx'], 4); // three 401 + one 404
  assert.equal(agg.byClass['3xx'], 1);
  assert.equal(agg.byClass['2xx'], 1);

  // Most frequent (status, path) pair comes first.
  assert.deepEqual(agg.byStatusPath[0], {
    status: 401,
    path: '/v1/chat/completions',
    count: 3,
  });
});

test('aggregate ignores records with a non-finite status', () => {
  const agg = aggregate([{ path: '/x' }, { httpStatus: 'oops', path: '/y' }, { httpStatus: 500 }]);
  assert.equal(agg.total, 1);
  assert.equal(agg.byClass['5xx'], 1);
});

test('aggregate groups the same path with differing query strings together', () => {
  const agg = aggregate([
    { httpStatus: 404, path: '/api/v1/agents/a?x=1' },
    { httpStatus: 404, path: '/api/v1/agents/a?x=2' },
  ]);
  assert.equal(agg.byStatusPath.length, 1);
  assert.equal(agg.byStatusPath[0].count, 2);
});

test('formatReport renders totals, class lines, and a capped top table', () => {
  // Distinct counts so ordering is unambiguous: 401(3) > 404(2) > 302(1).
  const agg = aggregate([
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 401, path: '/v1/chat/completions' },
    { httpStatus: 404, path: '/wp-login.php' },
    { httpStatus: 404, path: '/wp-login.php' },
    { httpStatus: 302, path: '/api/auth/x' },
  ]);
  const report = formatReport(agg, { top: 2 });

  assert.match(report, /Total HTTP log records: 6/);
  assert.match(report, /4xx {2}5 {2}\(83\.3%\)/); // three 401 + two 404
  assert.match(report, /3xx {2}1 {2}\(16\.7%\)/);
  assert.match(report, /Top 2 \(status x path\):/);
  assert.match(report, /401 {2}\/v1\/chat\/completions/);
  // Capped at 2 rows → the lowest-count pair (302) is excluded.
  assert.ok(!report.includes('/api/auth/x'));
});

test('formatReport defaults top to 25 and handles an empty aggregate', () => {
  const report = formatReport(aggregate([]));
  assert.match(report, /Total HTTP log records: 0/);
  assert.match(report, /Top 25 \(status x path\):/);
});

test('parseArgs reads flags, applies env fallback, and sets defaults', () => {
  const cfg = parseArgs(
    ['--deployment', 'dep-1', '--filter', '@httpStatus:401', '--limit', '100', '--top', '5'],
    { RAILWAY_API_TOKEN: 'tok-env' },
  );
  assert.equal(cfg.token, 'tok-env');
  assert.equal(cfg.deploymentId, 'dep-1');
  assert.equal(cfg.filter, '@httpStatus:401');
  assert.equal(cfg.limit, 100);
  assert.equal(cfg.top, 5);

  // Defaults when flags are absent.
  const def = parseArgs([], {});
  assert.equal(def.limit, 5000);
  assert.equal(def.top, 25);
  assert.equal(def.token, undefined);

  // Explicit --token and short flags win / are honored.
  const cfg2 = parseArgs(['--token', 'tok-cli', '-d', 'dep-2', '-f', 'x', '-l', '7', '-t', '3'], {
    RAILWAY_TOKEN: 'tok-env2',
  });
  assert.equal(cfg2.token, 'tok-cli');
  assert.equal(cfg2.deploymentId, 'dep-2');
});

test('fetchHttpLogs posts the right query/variables and returns httpLogs', async () => {
  const calls = [];
  const fakeFetch = async (url, init) => {
    calls.push({ url, init });
    return {
      ok: true,
      async json() {
        return { data: { httpLogs: [{ httpStatus: 404, path: '/x' }] } };
      },
    };
  };

  const records = await fetchHttpLogs(
    { token: 'tok', deploymentId: 'dep-1', start: 'S', end: 'E', filter: 'F', limit: 42 },
    fakeFetch,
  );

  assert.equal(calls.length, 1);
  assert.equal(calls[0].url, RAILWAY_GRAPHQL_ENDPOINT);
  assert.equal(calls[0].init.headers.Authorization, 'Bearer tok');
  const body = JSON.parse(calls[0].init.body);
  assert.equal(body.query, HTTP_LOGS_QUERY);
  assert.deepEqual(body.variables, {
    deploymentId: 'dep-1',
    startDate: 'S',
    endDate: 'E',
    filter: 'F',
    limit: 42,
  });
  assert.deepEqual(records, [{ httpStatus: 404, path: '/x' }]);
});

test('fetchHttpLogs returns [] when the API yields no logs array', async () => {
  const fakeFetch = async () => ({ ok: true, async json() { return { data: {} }; } });
  const records = await fetchHttpLogs({ token: 't', deploymentId: 'd' }, fakeFetch);
  assert.deepEqual(records, []);
});

test('fetchHttpLogs throws on missing token or deployment', async () => {
  await assert.rejects(() => fetchHttpLogs({ deploymentId: 'd' }, async () => {}), /Missing Railway API token/);
  await assert.rejects(() => fetchHttpLogs({ token: 't' }, async () => {}), /Missing deployment id/);
});

test('fetchHttpLogs surfaces HTTP and GraphQL errors', async () => {
  const httpErr = async () => ({ ok: false, status: 403, async text() { return 'forbidden'; } });
  await assert.rejects(
    () => fetchHttpLogs({ token: 't', deploymentId: 'd' }, httpErr),
    /Railway API HTTP 403: forbidden/,
  );

  const gqlErr = async () => ({
    ok: true,
    async json() {
      return { errors: [{ message: 'bad field' }] };
    },
  });
  await assert.rejects(
    () => fetchHttpLogs({ token: 't', deploymentId: 'd' }, gqlErr),
    /Railway GraphQL error/,
  );
});

test('fetchHttpLogs tolerates a text() failure on a non-ok response', async () => {
  const fakeFetch = async () => ({
    ok: false,
    status: 500,
    async text() {
      throw new Error('stream broke');
    },
  });
  await assert.rejects(
    () => fetchHttpLogs({ token: 't', deploymentId: 'd' }, fakeFetch),
    /Railway API HTTP 500: $/,
  );
});
